function dsSyncDiagNoteDrop(path, kind, stats){
  try{
    if(!stats) return;
    stats.droppedCount = Number(stats.droppedCount || 0) + 1;
    const safeKind = String(kind || 'invalid');
    stats.droppedKinds = stats.droppedKinds || {};
    stats.droppedKinds[safeKind] = Number(stats.droppedKinds[safeKind] || 0) + 1;
    if(path && (!stats.droppedPaths || stats.droppedPaths.length < 8)){
      (stats.droppedPaths || (stats.droppedPaths = [])).push(String(path));
    }
  }catch(_){ }
}
function dsSanitizeCloudPayload(value, path, seen, stats){
  try{
    if(value === undefined){ dsSyncDiagNoteDrop(path, 'undefined', stats); return undefined; }
    if(value === null) return null;
    const t = typeof value;
    if(t === 'string' || t === 'boolean') return value;
    if(t === 'number') return Number.isFinite(value) ? value : null;
    if(t === 'bigint') return String(value);
    if(t === 'function' || t === 'symbol'){ dsSyncDiagNoteDrop(path, t, stats); return undefined; }

    if(t !== 'object') return value;

    try{
      if(typeof window !== 'undefined'){
        if(value === window || value === document){ dsSyncDiagNoteDrop(path, 'window', stats); return undefined; }
        if(typeof Node !== 'undefined' && value instanceof Node){ dsSyncDiagNoteDrop(path, 'dom-node', stats); return undefined; }
        if(typeof Event !== 'undefined' && value instanceof Event){ dsSyncDiagNoteDrop(path, 'event', stats); return undefined; }
      }
    }catch(_){ }

    try{ if(typeof Blob !== 'undefined' && value instanceof Blob){ dsSyncDiagNoteDrop(path, 'blob', stats); return undefined; } }catch(_){ }
    try{ if(typeof File !== 'undefined' && value instanceof File){ dsSyncDiagNoteDrop(path, 'file', stats); return undefined; } }catch(_){ }
    if(value instanceof Date) return value.getTime();
    if(value instanceof RegExp) return String(value);
    if(value instanceof Error) return { name:String(value.name||'Error'), message:String(value.message||'') };
    if(typeof URL !== 'undefined' && value instanceof URL) return String(value);
    if(typeof Map !== 'undefined' && value instanceof Map){
      const obj = {};
      let idx = 0;
      value.forEach(function(v, k){
        const key = String(k);
        const sv = dsSanitizeCloudPayload(v, (path||'root') + '.<map>.' + key, seen, stats);
        if(sv !== undefined) obj[key] = sv;
        idx += 1;
      });
      return obj;
    }
    if(typeof Set !== 'undefined' && value instanceof Set){
      const arr = [];
      let idx = 0;
      value.forEach(function(v){
        const sv = dsSanitizeCloudPayload(v, (path||'root') + '.<set>[' + idx + ']', seen, stats);
        if(sv !== undefined) arr.push(sv);
        idx += 1;
      });
      return arr;
    }
    try{ if(value && typeof value.toMillis === 'function') return Number(value.toMillis()); }catch(_){ }
    try{ if(value && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number'){ return (value.seconds * 1000) + Math.floor((value.nanoseconds||0) / 1000000); } }catch(_){ }

    if(Array.isArray(value)){
      if(seen.has(value)){ dsSyncDiagNoteDrop(path, 'circular-array', stats); return []; }
      seen.add(value);
      const arr = [];
      for(let i=0;i<value.length;i++){
        const sv = dsSanitizeCloudPayload(value[i], (path||'root') + '[' + i + ']', seen, stats);
        if(sv !== undefined) arr.push(sv);
      }
      seen.delete(value);
      return arr;
    }

    const proto = Object.getPrototypeOf(value);
    const plain = !proto || proto === Object.prototype;
    if(!plain){
      try{
        if(value && typeof value.toJSON === 'function'){
          const j = value.toJSON();
          return dsSanitizeCloudPayload(j, (path||'root') + '.toJSON', seen, stats);
        }
      }catch(_){ }
      dsSyncDiagNoteDrop(path, 'non-plain-object', stats);
      return undefined;
    }

    if(seen.has(value)){ dsSyncDiagNoteDrop(path, 'circular-object', stats); return undefined; }
    seen.add(value);
    const out = {};
    Object.keys(value).forEach(function(key){
      const sv = dsSanitizeCloudPayload(value[key], (path ? path + '.' : '') + key, seen, stats);
      if(sv !== undefined) out[key] = sv;
    });
    seen.delete(value);
    return out;
  }catch(_){
    dsSyncDiagNoteDrop(path, 'sanitize-exception', stats);
    return undefined;
  }
}

function dsPruneProblemSyncFields(root){
  try{
    const topKeys = ['inboxAssignments','inboxSubmissions','assignments','submissions'];
    topKeys.forEach(function(topKey){
      const list = root && Array.isArray(root[topKey]) ? root[topKey] : null;
      if(!list) return;
      list.forEach(function(row){
        if(!row || typeof row !== 'object') return;
        ['payloadSubmitted','payloadDraft','payload'].forEach(function(payloadKey){
          const payload = row[payloadKey];
          if(!payload || typeof payload !== 'object') return;
          const pet = payload.pet;
          if(!pet || typeof pet !== 'object') return;
          try{ delete pet.profilePhoto; }catch(_){ try{ pet.profilePhoto = ''; }catch(__){} }
          try{ delete pet.vaccinationPassPhoto; }catch(_){ try{ pet.vaccinationPassPhoto = ''; }catch(__){} }
        });
      });
    });
  }catch(_){ }
  return root;
}

function dsPrepareCloudPayload(src){
  const stats = { droppedCount:0, droppedPaths:[], droppedKinds:{} };
  const clean = dsPruneProblemSyncFields(dsSanitizeCloudPayload(src, 'payload', new WeakSet(), stats) || {});
  return { clean, stats };
}


function dsStrictJsonReplacer(key, value){
  try{
    if(value === undefined) return null;
    const t = typeof value;
    if(t === 'function' || t === 'symbol') return null;
    if(t === 'bigint') return String(value);
    if(t === 'number') return Number.isFinite(value) ? value : null;
    if(value === null) return null;
    if(value instanceof Date) return value.getTime();
    if(value instanceof RegExp) return String(value);
    if(value instanceof Error) return { name:String(value.name||'Error'), message:String(value.message||'') };
    try{ if(typeof URL !== 'undefined' && value instanceof URL) return String(value); }catch(_){ }
    try{ if(typeof Blob !== 'undefined' && value instanceof Blob) return null; }catch(_){ }
    try{ if(typeof File !== 'undefined' && value instanceof File) return null; }catch(_){ }
    try{ if(typeof window !== 'undefined'){ if(value === window || value === document) return null; if(typeof Node !== 'undefined' && value instanceof Node) return null; if(typeof Event !== 'undefined' && value instanceof Event) return null; } }catch(_){ }
    try{ if(value && typeof value.toMillis === 'function') return Number(value.toMillis()); }catch(_){ }
    try{ if(value && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number') return (value.seconds * 1000) + Math.floor((value.nanoseconds||0) / 1000000); }catch(_){ }
    try{ if(typeof Map !== 'undefined' && value instanceof Map) return Object.fromEntries(Array.from(value.entries()).map(function(entry){ return [String(entry[0]), entry[1]]; })); }catch(_){ }
    try{ if(typeof Set !== 'undefined' && value instanceof Set) return Array.from(value.values()); }catch(_){ }
    if(Array.isArray(value)) return value;
    if(value && typeof value === 'object'){
      const proto = Object.getPrototypeOf(value);
      if(proto && proto !== Object.prototype){
        try{ if(typeof value.toJSON === 'function') return value.toJSON(); }catch(_){ }
        const out = {};
        try{ Object.keys(value).forEach(function(k){ out[k] = value[k]; }); }catch(_){ }
        return out;
      }
    }
    return value;
  }catch(_){
    return null;
  }
}
function dsPrepareCloudPayloadStrict(src){
  try{
    const json = JSON.stringify(src, dsStrictJsonReplacer);
    const clean = dsPruneProblemSyncFields(json ? JSON.parse(json) : {});
    return { clean: clean || {}, stats:{ mode:'json-replacer' } };
  }catch(err){
    return { clean: {}, stats:{ mode:'json-replacer', error:String((err && err.message) || err || 'unknown') } };
  }
}

function dsTracePayloadSections(payload){
  const out = { first:null, sections:[], summary:'' };
  try{
    const root = (payload && typeof payload === 'object') ? payload : {};
    const keys = Object.keys(root || {});
    const seen = new WeakSet();
    function mark(section, path, kind){
      const row = { section:String(section||'payload'), path:String(path||'payload'), kind:String(kind||'invalid') };
      if(!out.first) out.first = row;
      return row;
    }
    function inspect(value, path, section, inArray){
      if(value === undefined) return mark(section, path, 'undefined');
      if(value === null) return null;
      const t = typeof value;
      if(t === 'string' || t === 'boolean') return null;
      if(t === 'number') return Number.isFinite(value) ? null : mark(section, path, 'non-finite-number');
      if(t === 'bigint') return mark(section, path, 'bigint');
      if(t === 'function' || t === 'symbol') return mark(section, path, t);
      if(t !== 'object') return null;
      try{
        if(typeof window !== 'undefined'){
          if(value === window || value === document) return mark(section, path, 'window');
          if(typeof Node !== 'undefined' && value instanceof Node) return mark(section, path, 'dom-node');
          if(typeof Event !== 'undefined' && value instanceof Event) return mark(section, path, 'event');
        }
      }catch(_){ }
      try{ if(typeof Blob !== 'undefined' && value instanceof Blob) return mark(section, path, 'blob'); }catch(_){ }
      try{ if(typeof File !== 'undefined' && value instanceof File) return mark(section, path, 'file'); }catch(_){ }
      if(value instanceof Date || value instanceof RegExp || value instanceof Error) return null;
      try{ if(typeof URL !== 'undefined' && value instanceof URL) return null; }catch(_){ }
      if(Array.isArray(value)){
        if(inArray) return mark(section, path, 'nested-array');
        if(seen.has(value)) return mark(section, path, 'circular-array');
        seen.add(value);
        for(let i=0;i<value.length;i++){
          const fail = inspect(value[i], path + '[' + i + ']', section, true);
          if(fail){ seen.delete(value); return fail; }
        }
        seen.delete(value);
        return null;
      }
      const proto = Object.getPrototypeOf(value);
      const plain = !proto || proto === Object.prototype;
      if(!plain) return mark(section, path, 'non-plain-object');
      if(seen.has(value)) return mark(section, path, 'circular-object');
      seen.add(value);
      const keys2 = Object.keys(value || {});
      for(let i=0;i<keys2.length;i++){
        const k = keys2[i];
        const fail = inspect(value[k], path + '.' + k, section, false);
        if(fail){ seen.delete(value); return fail; }
      }
      seen.delete(value);
      return null;
    }
    keys.forEach(function(key){
      try{
        const fail = inspect(root[key], 'payload.' + key, key, false);
        out.sections.push(fail ? (String(key) + ':FAIL<' + fail.kind + '> @ ' + fail.path) : (String(key) + ':ok'));
      }catch(err){
        out.sections.push(String(key) + ':TRACEERR<' + String((err && err.message) || err || 'unknown') + '>');
        if(!out.first) out.first = { section:String(key), path:'payload.' + String(key), kind:'trace-error' };
      }
    });
    out.summary = out.sections.slice(0,6).join(' | ');
  }catch(err){
    out.first = { section:'payload', path:'payload', kind:'trace-error:' + String((err && err.message) || err || 'unknown') };
    out.summary = 'trace-error';
  }
  return out;
}
