async function loadOrCreateUserProfile(user){
  if(!CLOUD.enabled || !user) return null;
  const uid = user.uid;
  const email = (user.email||"").toLowerCase();
  // Admin-Whitelist hat Vorrang
  const isAdminEmail = CLOUD.adminEmails.map(x=>String(x).toLowerCase()).includes(email);
  const ref = cloudUserDoc(uid);
  let snap = null;
  try{ snap = await ref.get(); }catch(e){ console.warn('User profile read failed', e); }
  if(!snap || !snap.exists){
    const role = isAdminEmail ? ROLES.ADMIN : ROLES.CUSTOMER;
    let pendingName = '';
    try{ pendingName = (localStorage.getItem('dstest_pending_name')||'').trim(); }catch(_){ }
    if(pendingName){ try{ localStorage.removeItem('dstest_pending_name'); }catch(_){ } }
    const displayName = pendingName || ((user.email||'').split('@')[0]||'');
    const profile = {
      uid,
      email: user.email||"",
      displayName,
      role,
      createdAt: Date.now()
    };
    try{ await ref.set(profile, {merge:true}); }catch(e){ console.warn('User profile create failed', e); }
    return profile;
  }
  const data = snap.data()||{};
  // falls jemand in Whitelist ist: immer admin
  if(isAdminEmail && data.role !== ROLES.ADMIN){
    try{ await ref.set({role: ROLES.ADMIN}, {merge:true}); }catch(_){ }
    data.role = ROLES.ADMIN;
  }
  return {
    uid,
    email: data.email || user.email || "",
    displayName: (data.displayName || ((user.email||'').split('@')[0]||'')),
    role: data.role || (isAdminEmail ? ROLES.ADMIN : ROLES.CUSTOMER),
    createdAt: data.createdAt || 0
  };
}
async function cloudLoadState(){
  if(!CLOUD.enabled) return null;
  const ref = cloudStateRef();
  if(!ref) return null;
  const snap = await ref.get();
  if(!snap.exists) return null;
  const data = snap.data();
  if(!data || !data.payload) return null;
  CLOUD._lastRemoteStamp = Number(data.updatedAt || 0);
  SYNC.cloudLastSeenAt = CLOUD._lastRemoteStamp;
  updateSyncUI();
  return data.payload;
}
// --- Robust Startup Sync Helpers ---
// In iOS/Safari kann es vorkommen, dass beim Reload der erste Firestore-Read leer/zu früh ist.
// Diese Helper sorgen dafür, dass Remote-State zuverlässig übernommen und lokal gespeichert wird.
function isStateEffectivelyEmpty(s){
  try{
    const pets = Array.isArray(s?.pets) ? s.pets.filter(x=>x && !x.isPlaceholder) : [];
    const customers = Array.isArray(s?.customers) ? s.customers.filter(x=>x) : [];
    const docs = Array.isArray(s?.docs) ? s.docs.filter(x=>x) : [];
    const dogs = Array.isArray(s?.dogs) ? s.dogs.filter(x=>x && !x.isPlaceholder) : [];
    return (pets.length===0 && customers.length===0 && docs.length===0 && dogs.length===0);
  }catch(_){
    return true;
  }
}
// --- Phase 1: Cloud-Datenfluss Merge-Strategie ---
// Ziel: Remote darf lokale Stammdaten (Hunde/Kunden) nicht "leer" überschreiben.
function _mergeById(remoteArr, localArr){
  const m = new Map();
  for (const it of (remoteArr||[])) {
    if (it && it.id) m.set(it.id, it);
  }
  for (const it of (localArr||[])) {
    if (!it || !it.id) continue;
    const r = m.get(it.id);
    if (!r) { m.set(it.id, it); continue; }
    const rt = Number(r.updatedAt || r._updatedAt || 0);
    const lt = Number(it.updatedAt || it._updatedAt || 0);
    if (lt > rt) m.set(it.id, it);
  }
  return Array.from(m.values());
}
function _shallowMergeObj(a, b){
  if (a && typeof a === 'object' && !Array.isArray(a) && b && typeof b === 'object' && !Array.isArray(b)){
    return { ...a, ...b };
  }
  return (a !== undefined) ? a : b;
}
function mergeStatePreferRemote(remoteRaw, localRaw){
  const remote = remoteRaw || {};
  const local = localRaw || {};
  const out = { ...local, ...remote };
  // Arrays: ID-basiert mergen (remote + lokale Ergänzungen, pro Item jüngeres gewinnt)
  const idArrays = [
    'customers','pets','dogs','stays','invoices','docs','meds','medications','hygieneLogs','tasks','worksheets','entries','behaviorAssessments'
  ];
  for (const k of idArrays){
    if (Array.isArray(remote[k]) || Array.isArray(local[k])){
      out[k] = _mergeById(remote[k], local[k]);
    }
  }
  // Objekte: remote überschreibt, aber lokale Defaults bleiben erhalten
  const objKeys = ['settings','templates','company','meta','roles'];
  for (const k of objKeys){
    out[k] = _shallowMergeObj(remote[k], local[k]);
  }
  return out;
}
// --- /Merge-Strategie ---
function applyRemoteState(remote, remoteStamp, source){
  if(!remote) return false;
  try{
    // Merge: Remote ist nicht alleinige Wahrheit, lokale Stammdaten dürfen nicht verschwinden
    state = mergeStatePreferRemote(remote, state);
    // Falls der Remote-State keinen Stempel trägt: konservativ setzen
    if(remoteStamp && (!state._cloudUpdatedAt || Number(state._cloudUpdatedAt) < Number(remoteStamp))){
      state._cloudUpdatedAt = Number(remoteStamp);
    }
    ensureStateShape();
    ensureContractDefaults();
    migrateToV2();
    pruneInvoiceDocs();
    ensureDefaultDog();
    saveState(); // schreibt in localStorage + setzt _localUpdatedAt
    renderDogs();
    renderDocs();
    renderInvoiceList();
    // Home/Panel nicht erzwingen – wir lassen die aktuelle Ansicht
    try{ console.log("[SYNC] Applied remote state from", source||"unknown", "stamp", remoteStamp||0); }catch(_){ }
    return true;
  }catch(e){
    console.error("applyRemoteState failed", e);
    return false;
  }
}
async function cloudLoadStateWithRetry(maxTries=3){
  let lastErr = null;
  for(let i=0;i<maxTries;i++){
    try{
      const remote = await cloudLoadState();
      if(remote) return {remote, err:null};
    }catch(e){
      lastErr = e;
    }
    // kurzer Backoff – Safari/iOS braucht manchmal einen Tick nach Auth/Persistenz
    await new Promise(r=>setTimeout(r, 250 + i*250));
  }
  return {remote:null, err:lastErr};
}
function cloudPushQueued(){
  if(!CLOUD.enabled) return;
  clearTimeout(CLOUD._pushTimer);
  SYNC.cloudPending = true;
  updateSyncUI();
  try{ dsSetSyncDiag('cloudPush:queued delay=700 · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
  CLOUD._pushTimer = setTimeout(()=>cloudPushNow().catch(console.error), 700);
}
function cloudSchedulePush(){
  try{
    cloudPushQueued();
    return true;
  }catch(err){
    try{ console.warn('cloudSchedulePush fallback failed, pushing now', err); }catch(_){ }
    try{ Promise.resolve(cloudPushNow()).catch(console.error); return true; }catch(_){ }
  }
  return false;
}
async function cloudPushNow(){
  if(!CLOUD.enabled) return;
  if(!CLOUD.user) throw new Error("Nicht angemeldet");
  SYNC.cloudPending = true;
  try{ dsSetSyncDiag('cloudPush:start user=' + String((CLOUD.user && (CLOUD.user.email || CLOUD.user.uid)) || '--') + ' · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
  updateSyncUI();
  const stamp = Date.now();
  // Marker im State, damit wir Remote-Updates sauber vergleichen können
  try{ state._cloudUpdatedAt = stamp; state._localUpdatedAt = stamp; }catch(_){/* ignore */}
  const prepared = dsPrepareCloudPayload(state);
  const safeState = prepared && prepared.clean ? prepared.clean : {};
  const payloadTrace = dsTracePayloadSections(safeState);
  try{ window.__dsPayloadTrace = payloadTrace; }catch(_){ }
  try{
    if(safeState && typeof safeState === 'object'){
      safeState._cloudUpdatedAt = stamp;
      if(safeState._localUpdatedAt == null) safeState._localUpdatedAt = stamp;
    }
  }catch(_){ }
  try{
    const dropped = Number((prepared && prepared.stats && prepared.stats.droppedCount) || 0);
    if(payloadTrace && payloadTrace.first){
      const first = payloadTrace.first || {};
      dsSetSyncDiag('payloadTrace:first section=' + String(first.section || '--') + ' kind=' + String(first.kind || '--') + ' path=' + String(first.path || '--') + ' · ' + dsSyncDiagStateSummary(), true);
    }else if(dropped > 0){
      const sample = ((prepared && prepared.stats && prepared.stats.droppedPaths) || []).slice(0,3).join(', ');
      dsSetSyncDiag('cloudPush:sanitized drop=' + String(dropped) + (sample ? ' sample=' + sample : '') + ' · ' + dsSyncDiagStateSummary(), false);
    }
  }catch(_){ }
  // last write wins (v1). Später: echtes Merge pro Objekt.
  try{
    const ref = cloudStateRef();
    if(!ref){ try{ dsSetSyncDiag('cloudPush:no-ref · ' + dsSyncDiagStateSummary(), true); }catch(_){ } return; }
    await ref.set({
      payload: safeState,
      updatedAt: stamp,
      updatedBy: CLOUD.user.email || CLOUD.user.uid
    }, {merge: true});
    try{ dsSetSyncDiag('cloudPush:ok updatedAt=' + String(stamp) + ' drop=' + String((prepared && prepared.stats && prepared.stats.droppedCount) || 0) + ' · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
    CLOUD.lastPushOkAt = stamp;
    CLOUD.lastPushError = "";
    SYNC.cloudLastOkAt = stamp;
    SYNC.cloudLastError = "";
    SYNC.cloudPending = false;
  }catch(e){
    const errMsg = String(e?.message||e||"Cloud write failed");
    const sample = ((prepared && prepared.stats && prepared.stats.droppedPaths) || []).slice(0,4).join(', ');
    const first = (payloadTrace && payloadTrace.first) || null;
    const trace = first ? (' first=' + String(first.section || '--') + '/' + String(first.kind || '--') + '@' + String(first.path || '--')) : (payloadTrace && payloadTrace.summary ? (' sections=' + String(payloadTrace.summary || '').slice(0,220)) : '');
    let detail = 'msg=' + errMsg + trace + (((prepared && prepared.stats && prepared.stats.droppedCount) || 0) ? ' drop=' + String((prepared && prepared.stats && prepared.stats.droppedCount) || 0) : '') + (sample ? ' sample=' + sample : '');
    try{ dsSetSyncDiag('cloudPush:fail ' + detail + ' · ' + dsSyncDiagStateSummary(), true); }catch(_){ }
    let retried = false;
    try{
      const strictPrepared = dsPrepareCloudPayloadStrict(state);
      const strictState = (strictPrepared && strictPrepared.clean) ? strictPrepared.clean : {};
      try{ if(strictState && typeof strictState === 'object'){ strictState._cloudUpdatedAt = stamp; if(strictState._localUpdatedAt == null) strictState._localUpdatedAt = stamp; } }catch(_){ }
      const strictTrace = dsTracePayloadSections(strictState);
      try{ window.__dsPayloadTraceStrict = strictTrace; }catch(_){ }
      try{ dsSetSyncDiag('cloudPush:retry-strict mode=' + String((strictPrepared && strictPrepared.stats && strictPrepared.stats.mode) || 'json') + ((strictPrepared && strictPrepared.stats && strictPrepared.stats.error) ? ' prepErr=' + String(strictPrepared.stats.error) : '') + ' · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
      const ref2 = cloudStateRef();
      if(ref2){
        await ref2.set({
          payload: strictState,
          updatedAt: stamp,
          updatedBy: CLOUD.user.email || CLOUD.user.uid
        }, {merge:true});
        retried = true;
        const strictFirst = (strictTrace && strictTrace.first) || null;
        const strictDetail = strictFirst ? (' strictFirst=' + String(strictFirst.section || '--') + '/' + String(strictFirst.kind || '--') + '@' + String(strictFirst.path || '--')) : '';
        try{ dsSetSyncDiag('cloudPush:retry-ok updatedAt=' + String(stamp) + strictDetail + ' · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
        CLOUD.lastPushOkAt = stamp;
        CLOUD.lastPushError = "";
        SYNC.cloudLastOkAt = stamp;
        SYNC.cloudLastError = "";
        SYNC.cloudPending = false;
      }
    }catch(retryErr){
      const retryMsg = String((retryErr && retryErr.message) || retryErr || 'retry-failed');
      const strictTrace = (typeof window !== 'undefined' && window.__dsPayloadTraceStrict) ? window.__dsPayloadTraceStrict : null;
      const strictFirst = (strictTrace && strictTrace.first) || null;
      const retryTrace = strictFirst ? (' strictFirst=' + String(strictFirst.section || '--') + '/' + String(strictFirst.kind || '--') + '@' + String(strictFirst.path || '--')) : (strictTrace && strictTrace.summary ? (' strictSections=' + String(strictTrace.summary || '').slice(0,220)) : '');
      detail += ' retry=' + retryMsg + retryTrace;
      try{
        const probePayload = (typeof strictState !== 'undefined' && strictState && typeof strictState === 'object') ? strictState : ((safeState && typeof safeState === 'object') ? safeState : {});
        const probeRef = cloudStateRef();
        const probeRows = await dsProbeCloudSuspectSections(probeRef, probePayload);
        const firstProbe = Array.isArray(probeRows) ? probeRows.find(function(x){ return x && x.kind && x.kind !== 'no-fail-found'; }) : null;
        if(firstProbe){
          detail += ' probe=' + String(firstProbe.section || '--') + '/' + String(firstProbe.kind || '--') + '@' + String(firstProbe.path || '--');
        }else if(Array.isArray(probeRows) && probeRows.length){
          detail += ' probe=' + probeRows.map(function(x){ return String((x && x.section) || '--') + ':' + String((x && x.kind) || '--'); }).join('|').slice(0,220);
        }
      }catch(probeErr){
        detail += ' probeErr=' + String((probeErr && probeErr.message) || probeErr || 'unknown');
      }
      try{ dsSetSyncDiag('cloudPush:retry-fail ' + detail + ' · ' + dsSyncDiagStateSummary(), true); }catch(_){ }
    }
    if(!retried){
      CLOUD.lastPushError = detail;
      SYNC.cloudLastError = CLOUD.lastPushError;
      SYNC.cloudPending = false;
      throw e;
    }
  }finally{
    updateSyncUI();
  }
}
