async function fetchInboxAssignmentCloudCustomers(){
  const diag = { cloudEnabled: !!(CLOUD && CLOUD.enabled), loaded: 0, source: '', error: '' };
  const out = [];
  const seen = new Set();
  const add = (raw, source='cloud-users')=>{
    if(!raw || typeof raw !== 'object') return;
    const role = String(raw.role || raw.type || '').trim().toLowerCase();
    if(role && role !== 'customer') return;
    const portalUid = String(raw.uid || raw.portalUid || raw.userUid || raw.id || '').trim();
    const email = String(raw.email || raw.mail || '').trim().toLowerCase();
    const name = String(raw.displayName || raw.name || raw.fullName || '').trim();
    const phone = String(raw.phone || raw.tel || raw.mobile || '').trim();
    const key = String(portalUid || email || name || phone).toLowerCase();
    if(!key || seen.has(key)) return;
    seen.add(key);
    out.push({
      id: portalUid || email || name,
      customerId: portalUid || email || name,
      portalUid,
      name: name || email || phone || 'Kunde',
      email,
      phone,
      source
    });
  };
  try{
    if(!(CLOUD && CLOUD.enabled) || !CLOUD.db){
      window.__dsInboxAssignDiag = { ...diag, error: 'cloud-disabled' };
      __inboxAssignmentCloudCustomers = [];
      return [];
    }
    try{
      const snap = await cloudUsersCol().limit(300).get();
      snap.forEach(doc=>add({ id: doc.id, uid: doc.id, ...(doc.data() || {}) }, 'orgs.users'));
      diag.source = 'orgs.users';
    }catch(err){
      diag.error = String((err && (err.code || err.message)) || err || 'users-query-failed');
    }
    if(!out.length){
      try{
        const legacy = await CLOUD.db.collection(String(CLOUD.orgId || 'doggystyle')).collection('users').limit(300).get();
        legacy.forEach(doc=>add({ id: doc.id, uid: doc.id, ...(doc.data() || {}) }, 'legacy.users'));
        if(out.length) diag.source = 'legacy.users';
      }catch(err){
        const msg = String((err && (err.code || err.message)) || err || 'legacy-query-failed');
        diag.error = diag.error ? `${diag.error} | ${msg}` : msg;
      }
    }
  }catch(e){
    diag.error = String((e && (e.code || e.message)) || e || 'unknown-error');
  }
  __inboxAssignmentCloudCustomers = out.slice();
  window.__dsInboxAssignDiag = { ...diag, loaded: out.length, source: diag.source || '' };
  return out;
}

function getMergedInboxAssignmentCustomers(){
  const merged = [];
  const seen = new Set();
  const add = (c)=>{
    if(!c) return;
    const portalUid = String(c.portalUid || c.uid || '').trim();
    const email = String(c.email || '').trim().toLowerCase();
    const id = String(c.id || c.customerId || '').trim();
    const name = String(c.name || '').trim();
    const phone = String(c.phone || '').trim();
    const key = String(portalUid || email || id || name || phone).toLowerCase();
    if(!key || seen.has(key)) return;
    seen.add(key);
    merged.push({
      id: portalUid || id || email || name,
      customerId: id || portalUid || email || name,
      portalUid,
      name: name || email || phone || 'Kunde',
      email,
      phone,
      source: c.source || ''
    });
  };
  try{ (Array.isArray(__inboxAssignmentCloudCustomers) ? __inboxAssignmentCloudCustomers : []).forEach(add); }catch(_){ }
  try{ getInboxAssignmentLocalCustomers().forEach(add); }catch(_){ }
  return merged.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''), 'de'));
}

function populateInboxAssignmentControls(){
  const selCustomer = document.getElementById('assignCustomer');
  const selTemplate = document.getElementById('assignTemplate');
  if(!selCustomer || !selTemplate) return { customers: 0, templates: 0 };
  try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), beforeOptions: selCustomer.options ? selCustomer.options.length : 0 }; }catch(_){ }
  const prevCustomer = String(selCustomer.value || '');
  const prevTemplate = String(selTemplate.value || '');
  let canonicalCustomers = buildCanonicalCustomerList();
  if(!canonicalCustomers.length){
    try{ renderDogs(); }catch(_){ }
    try{ refreshCustomerSelect(); }catch(_){ }
    canonicalCustomers = buildCanonicalCustomerList();
  }
  const mergedCustomers = getMergedInboxAssignmentCustomers();
  const customers = canonicalCustomers.length ? canonicalCustomers : mergedCustomers;
  const templatesForAssign = getInboxAssignmentTemplatesResolved();
  try{
    window.__dsInboxAssignDiag = {
      ...(window.__dsInboxAssignDiag||{}),
      canonicalCustomers: canonicalCustomers.length,
      mergedCustomers: mergedCustomers.length,
      chosenCustomers: customers.length,
      stateCustomers: Array.isArray(state.customers)?state.customers.length:0,
      statePets: Array.isArray(state.pets)?state.pets.length:0,
      customerSelectOptions: Array.from(document.querySelectorAll('#customerSelect option')).filter(o=>String(o.value||'').trim()).length,
      assignCustomerOptionsBeforeRender: selCustomer.options ? selCustomer.options.length : 0,
      dogListItems: Array.from(document.querySelectorAll('#dogList .item')).length,
      dogListStrong: Array.from(document.querySelectorAll('#dogList .item strong')).length
    };
  }catch(_){ }

  selCustomer.innerHTML = '';
  if(!customers.length){
    selCustomer.disabled = true;
    selCustomer.innerHTML = '<option value="">Keine Kunden vorhanden</option>';
    try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), localCustomers: canonicalCustomers.length, mergedCustomers: mergedCustomers.length, stateCustomers: Array.isArray(state.customers)?state.customers.length:0, statePets: Array.isArray(state.pets)?state.pets.length:0, dogListItems: Array.from(document.querySelectorAll('#dogList .item strong')).length }; }catch(_){ }
  }else{
    selCustomer.disabled = false;
    selCustomer.innerHTML = '<option value="">Bitte auswählen…</option>';
    customers.forEach(c=>{
      const value = String(c.customerId || c.id || c.portalUid || c.email || '').trim();
      const fallbackName = String(c.name || [c.firstName||'', c.lastName||''].filter(Boolean).join(' ') || c.fullName || c.customerName || c.email || c.phone || value || 'Kunde').trim();
      const meta = [];
      if(c.email) meta.push(c.email);
      else if(c.phone) meta.push(c.phone);
      const label = meta.length ? `${fallbackName} · ${meta.join(' · ')}` : fallbackName;
      selCustomer.insertAdjacentHTML('beforeend', `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`);
    });
  }

  selTemplate.disabled = false;
  selTemplate.innerHTML = '<option value="">Bitte auswählen…</option>';
  templatesForAssign.forEach(t=>{
    selTemplate.insertAdjacentHTML('beforeend', `<option value="${escapeHtml(String(t.id||''))}">${escapeHtml(String(t.name||t.id||''))}</option>`);
  });

  if(prevCustomer && Array.from(selCustomer.options).some(o=>o.value === prevCustomer)) selCustomer.value = prevCustomer;
  if(prevTemplate && Array.from(selTemplate.options).some(o=>o.value === prevTemplate)) selTemplate.value = prevTemplate;
  try{
    const values = Array.from(selCustomer.options || []).map(o=>String(o.value||'').trim()).filter(Boolean);
    const labels = Array.from(selCustomer.options || []).map(o=>String(o.textContent||'').trim()).filter(Boolean);
    window.__dsInboxAssignDiag = {
      ...(window.__dsInboxAssignDiag||{}),
      assignCustomerOptionsAfterRender: selCustomer.options ? selCustomer.options.length : 0,
      assignCustomerValueOptions: values.length,
      assignCustomerLabelsPreview: labels.slice(0,5).join(' | ')
    };
  }catch(_){ }
  return { customers: customers.length, templates: templatesForAssign.length };
}

async function wireInboxAssignments(){
  const card = document.getElementById('taskAssignCard');
  const legacyCard = document.getElementById('adminTaskCard');
  const selCustomer = document.getElementById('assignCustomer');
  const selTemplate = document.getElementById('assignTemplate');
  const btnCreate = document.getElementById('btnAssignTask');
  const btnRefresh = document.getElementById('btnInboxRefresh');
  const msgEl = document.getElementById('assignMsg');
  const diagEl = document.getElementById('assignDiag');
  if(!selCustomer || !selTemplate || !btnCreate) return;

  if(legacyCard) legacyCard.remove();
  if(card) card.style.display = '';

  const setMsg = (txt, isErr=false)=>{
    if(!msgEl) return;
    msgEl.textContent = txt || '';
    msgEl.style.color = isErr ? '#ffb3b3' : '';
  };
  if(diagEl) diagEl.textContent = 'Diagnose: Start …';

  const setDiag = ()=>{
    if(!diagEl) return;
    try{
      const d = window.__dsInboxAssignDiag || {};
      const parts = [
        `Quelle=${d.source||'-'}`,
        `cloud=${d.loaded ?? '-'}`,
        `canonical=${d.canonicalCustomers ?? '-'}`,
        `merged=${d.mergedCustomers ?? '-'}`,
        `chosen=${d.chosenCustomers ?? '-'}`,
        `state.customers=${d.stateCustomers ?? '-'}`,
        `state.pets=${d.statePets ?? '-'}`,
        `customerSelect=${d.customerSelectOptions ?? '-'}`,
        `assign.after=${d.assignCustomerOptionsAfterRender ?? '-'}`,
        `assign.values=${d.assignCustomerValueOptions ?? '-'}`,
        `dogList=${d.dogListItems ?? '-'}`,
        `strong=${d.dogListStrong ?? '-'}`
      ];
      if(d.phase) parts.push(`phase=${d.phase}`);
      if(d.assignCustomerLabelsPreview) parts.push(`preview=${d.assignCustomerLabelsPreview}`);
      if(d.createStatus) parts.push(`create.status=${d.createStatus}`);
      if(d.createVia) parts.push(`create.via=${d.createVia}`);
      if(d.createCustomer) parts.push(`create.customer=${d.createCustomer}`);
      if(d.createTask) parts.push(`create.task=${d.createTask}`);
      if(d.error) parts.push(`error=${d.error}`);
      diagEl.textContent = 'Diagnose: ' + parts.join(' · ');
      diagEl.style.color = d.error ? '#ffb3b3' : '';
    }catch(e){
      diagEl.textContent = 'Diagnose: Fehler beim Lesen der Diagnosewerte';
      diagEl.style.color = '#ffb3b3';
    }
  };

  const applyRefreshResult = ()=>{
    const info = populateInboxAssignmentControls();
    const diag = window.__dsInboxAssignDiag || {};
    if(info.templates && !selTemplate.value) selTemplate.selectedIndex = 0;
    if(info.customers){
      const src = diag.source ? ` · Quelle: ${diag.source}` : '';
      setMsg(`Kunden: ${info.customers} · Aufgaben: ${info.templates}${src}`, false);
    }else{
      const detail = diag.error ? ` – ${diag.error}` : '';
      setMsg(`Keine Kunden gefunden${detail}`, true);
    }
    setDiag();
  };

  const refresh = async ()=>{
    try{ state = loadState(); }catch(_){ }
    try{ ensureStateShape(); }catch(_){ }
    try{
      window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), phase: 'local-start', source: 'local-only' };
    }catch(_){ }
    applyRefreshResult();
    const cloudPromise = (async()=>{
      try{
        await Promise.race([
          fetchInboxAssignmentCloudCustomers(),
          new Promise((_, reject)=>setTimeout(()=>reject(new Error('cloud-timeout')), 1800))
        ]);
      }catch(err){
        try{
          window.__dsInboxAssignDiag = {
            ...(window.__dsInboxAssignDiag||{}),
            error: String((err && err.message) || err || 'cloud-fetch-failed'),
            source: (window.__dsInboxAssignDiag && window.__dsInboxAssignDiag.source) || 'local-only',
            phase: 'cloud-fallback'
          };
        }catch(_){ }
      }
      applyRefreshResult();
    })();
    return cloudPromise;
  };

  btnRefresh?.addEventListener('click', ()=>{
    Promise.resolve().then(async()=>{
      await refresh();
      try{
        if(typeof window.__dsInboxReload === 'function'){
          const tasks = await window.__dsInboxReload();
          const count = Array.isArray(tasks) ? tasks.length : Number(window.__dsInboxLastCount||0);
          if(count > 0) setMsg(`Eingänge geladen: ${count}`, false);
          else setMsg('Keine Eingänge gefunden.', true);
        }
      }catch(err){
        console.error('inbox reload from refresh failed', err);
        setMsg('Eingänge-Aktualisierung fehlgeschlagen: ' + ((err && err.message) || err || 'reload-failed'), true);
      }
    }).catch(e=>{ console.error(e); setMsg('Aktualisieren fehlgeschlagen.', true); });
  });
  window.addEventListener('pageshow', ()=>{ refresh().catch(()=>{}); });
  document.addEventListener('visibilitychange', ()=>{ if(!document.hidden) refresh().catch(()=>{}); });
  document.querySelector('[data-tab="inbox"]')?.addEventListener('click', ()=>setTimeout(()=>refresh().catch(()=>{}), 0));

  btnCreate.onclick = async ()=>{
    try{
      const selectedCustomer = String(selCustomer.value || '').trim();
      const templateId = String(selTemplate.value || '').trim();
      try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'click', createVia: '', createCustomer: selectedCustomer || '-', createTask: templateId || '-' }; setDiag(); }catch(_){ }
      if(!selectedCustomer){ setMsg('Bitte zuerst einen Kunden auswählen.', true); try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'missing-customer' }; setDiag(); }catch(_){ } return; }
      if(!templateId){ setMsg('Bitte zuerst eine Aufgabe auswählen.', true); try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'missing-template' }; setDiag(); }catch(_){ } return; }

      const inlineCustomers = Array.isArray(window.__dsInboxInlineCustomers) ? window.__dsInboxInlineCustomers : [];
      const mergedCustomers = getMergedInboxAssignmentCustomers();
      const optionLabel = (()=>{ try{ return String(selCustomer.options[selCustomer.selectedIndex]?.textContent || '').trim(); }catch(_){ return ''; } })();
      let customer = inlineCustomers.find(c => String(c.customerId || c.id || c.portalUid || c.email || '').trim() === selectedCustomer)
        || mergedCustomers.find(c => String(c.customerId || c.id || c.portalUid || c.email || '').trim() === selectedCustomer)
        || inlineCustomers.find(c => String(c.email || '').trim().toLowerCase() === selectedCustomer.toLowerCase())
        || mergedCustomers.find(c => String(c.email || '').trim().toLowerCase() === selectedCustomer.toLowerCase())
        || inlineCustomers.find(c => optionLabel && `${String(c.name||'').trim()} · ${String(c.email||c.phone||'').trim()}`.trim() === optionLabel)
        || mergedCustomers.find(c => optionLabel && `${String(c.name||'').trim()} · ${String(c.email||c.phone||'').trim()}`.trim() === optionLabel);
      if(!customer){ setMsg('Kunde konnte nicht aufgelöst werden.', true); try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'customer-not-resolved', error: 'customer-not-resolved' }; setDiag(); }catch(_){ } return; }

      let portalUid = String(customer.portalUid || '').trim();
      let createVia = portalUid ? 'direct-portalUid' : 'local-only';
      if(!portalUid){
        const customerEmail = String(customer.email || '').trim().toLowerCase();
        const cloudCustomers = Array.isArray(window.__inboxAssignmentCloudCustomers) ? window.__inboxAssignmentCloudCustomers : [];
        const cloudMatch = cloudCustomers.find(c => String(c.email || c.mail || '').trim().toLowerCase() === customerEmail)
          || cloudCustomers.find(c => String(c.customerId || c.id || '').trim() === String(customer.customerId || '').trim());
        if(cloudMatch){
          portalUid = String(cloudMatch.portalUid || cloudMatch.portalUID || cloudMatch.userUid || cloudMatch.uid || cloudMatch.customerUid || '').trim();
          if(!customer.email && cloudMatch.email) customer.email = String(cloudMatch.email).trim();
          createVia = portalUid ? 'cloud-match' : createVia;
        }
      }
      const templateMeta = getInboxAssignmentTemplatesResolved().find(t => String(t.id) === templateId) || { id: templateId, name: templateId };
      const task = {
        customerUid: portalUid || '',
        customerEmail: String(customer.email || '').trim().toLowerCase(),
        customerName: customer.name || optionLabel || '',
        customerId: customer.customerId || portalUid || customer.email || '',
        taskId: templateId,
        templateId: templateId,
        title: templateMeta.name || templateId,
        status: 'open',
        createdAt: Date.now(),
        createdByUid: (CLOUD.user && CLOUD.user.uid) || '',
        createdByEmail: (CLOUD.user && CLOUD.user.email) || ''
      };
      const tasksCol = cloudTasksCol();
      if(!tasksCol){
        setMsg('❌ Cloud nicht bereit. Aufgabe konnte nicht freigegeben werden.', true);
        try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'cloud-unavailable', createVia, createCustomer: task.customerName || task.customerEmail || task.customerUid || '-', createTask: task.taskId, error: 'cloud-unavailable' }; setDiag(); }catch(_){ }
        return;
      }
      if(!portalUid && !task.customerEmail){
        setMsg('Kunde sichtbar, aber weder Portal-Konto noch E-Mail-Zuordnung vorhanden.', true);
        try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'missing-target', createVia, error: 'missing-target' }; setDiag(); }catch(_){ }
        return;
      }

      setMsg('Aufgabe wird erstellt …', false);
      try{ window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'writing', createVia: portalUid ? createVia : (createVia + '+email'), createCustomer: task.customerName || task.customerEmail || task.customerUid || '-', createTask: task.taskId, error: '' }; setDiag(); }catch(_){ }
      let created = null;
      if(tasksCol && typeof tasksCol.add === 'function'){
        created = await tasksCol.add(task);
      }else if(tasksCol && typeof tasksCol.doc === 'function'){
        const ref = tasksCol.doc();
        await ref.set(task);
        created = { id: ref.id };
      }else{
        throw new Error('cloud-tasks-unavailable');
      }
      state.inboxAssignments = Array.isArray(state.inboxAssignments) ? state.inboxAssignments : [];
      state.inboxAssignments.unshift({ id:(created && created.id) || ('asg_'+Date.now()), ...task });
      saveState();
      selTemplate.value = '';
      setMsg(`✅ Aufgabe freigegeben für ${customer.name || customer.email || portalUid || 'Kunde'}.`, false);
      try{ window.__dsInboxCreateStatus = 'created'; window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'created', createVia: portalUid ? createVia : (createVia + '+email'), createCustomer: task.customerName || task.customerEmail || task.customerUid || '-', createTask: task.taskId, error: '' }; setDiag(); }catch(_){ }
    }catch(e){
      console.error('create inbox assignment failed', e);
      setMsg(`❌ ${String((e && e.message) || e || 'Fehler beim Erstellen')}`, true);
      try{ window.__dsInboxCreateStatus = 'error'; window.__dsInboxAssignDiag = { ...(window.__dsInboxAssignDiag||{}), createStatus: 'error', error: String((e && e.message) || e || 'create-failed') }; setDiag(); }catch(_){ }
    }
  };

  refresh().catch(e=>{ console.error(e); setMsg('Initiales Laden fehlgeschlagen.', true); });
}

// ===== PREISLOGIK & STAFFELUNGEN =====
const PRICE_RULES_DEFAULT = {
  Tagesbetreuung: [
    { min: 30, price: 30 },
    { min: 14, price: 35 },
    { min: 7,  price: 37.5 },
    { min: 1,  price: 40 }
  ],
  Urlaubsbetreuung: [
    { min: 30, price: 35 },
    { min: 14, price: 40 },
    { min: 7,  price: 42.5 },
    { min: 1,  price: 45 }
  ]
};
// ===== PREISE (zentral, in Einstellungen editierbar) =====
const PRICING_DEFAULTS = {
  rules: JSON.parse(JSON.stringify(PRICE_RULES_DEFAULT)),
  holidayPercent: 10,
  // MwSt wird in der App als Netto/MwSt/Brutto ausgewiesen (Brutto bleibt Brutto)
  vatPercent: 19,
  extras: {
    specialTimesPercent: 10,   // f.special_times
    extraCarePercent: 10,      // f.extra_care
    medicationPerDay: 2,       // f.medication (pro Tag)
    walkExtraPrice: 15,        // f.walk_extra_count (pro zusätzl. Spaziergang)
    bandagePrice: 2.5,         // f.bandage_count (pro Stück)
    groomingPrice: 5,          // f.grooming_count (pro Stück)
    hygienePerDay: 0,          // optional (€/Tag)
    pickupDropoffPrice: 0,     // optional (€/Fahrt)
    sundayPercent: 0,          // optional (% auf Grundpreis)
    shortNoticePercent: 0      // optional (% auf Grundpreis)
  }
};
function getPricingSettings(){
  // bevorzugt: state.settings.pricing (wird mitgesynct), fallback: localStorage
  try{
    if(!window.state) return PRICING_DEFAULTS;
    state.settings = state.settings || {};
    let p = state.settings.pricing;
    if(!p){
      try{
        const raw = localStorage.getItem('ds_pricing_settings_v1');
        if(raw) p = JSON.parse(raw);
      }catch(_){}
    }
    // merge defaults (robust bei Teilständen)
    const out = JSON.parse(JSON.stringify(PRICING_DEFAULTS));
    if(p && typeof p === 'object'){
      if(p.rules && typeof p.rules === 'object') out.rules = p.rules;
      if(Number.isFinite(+p.holidayPercent)) out.holidayPercent = +p.holidayPercent;
      if(Number.isFinite(+p.vatPercent)) out.vatPercent = +p.vatPercent;
      if(p.extras && typeof p.extras === 'object'){
        for(const k of Object.keys(out.extras)){
          if(Number.isFinite(+p.extras[k])) out.extras[k] = +p.extras[k];
        }
      }
    }
    // write back normalized
    state.settings.pricing = out;
    try{ localStorage.setItem('ds_pricing_settings_v1', JSON.stringify(out)); }catch(_){}
    return out;
  }catch(_){
    return PRICING_DEFAULTS;
  }
}
function savePricingSettings(next){
  try{
    if(!next || typeof next !== 'object') return;
    state.settings = state.settings || {};
    state.settings.pricing = next;
    // Konsistenz: MwSt auch als globales Feld (wird von Rechnungen genutzt)
    if(Number.isFinite(+next.vatPercent)) state.settings.vatRate = +next.vatPercent;
    try{ localStorage.setItem('ds_pricing_settings_v1', JSON.stringify(next)); }catch(_){}
    saveState();
  }catch(e){
    console.error('savePricingSettings failed', e);
  }
}
function daysBetween(from, to){
  const ms = new Date(to) - new Date(from);
  return Math.max(1, Math.ceil(ms / (1000 * 60 * 60 * 24)));
}
// Feiertage Bayern (vereinfachte, praxisnahe Auswahl; Zeitraum-Berechnung offline)
function easterSunday(year){
  // Anonymous Gregorian algorithm (Meeus/Jones/Butcher)
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19*a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2*e + 2*i - h - k) % 7;
  const m = Math.floor((a + 11*h + 22*l) / 451);
  const month = Math.floor((h + l - 7*m + 114) / 31); // 3=March, 4=April
  const day = ((h + l - 7*m + 114) % 31) + 1;
  return new Date(Date.UTC(year, month-1, day));
}
function addDaysUTC(d, days){
  const x = new Date(d.getTime());
  x.setUTCDate(x.getUTCDate() + days);
  return x;
}
function formatYMD(d){
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth()+1).padStart(2,'0');
  const da = String(d.getUTCDate()).padStart(2,'0');
  return `${y}-${m}-${da}`;
}
function bavariaHolidaysSet(year){
  const set = new Set();
  const easter = easterSunday(year);
  // Fixe Feiertage (Bayern)
  ["01-01","01-06","05-01","10-03","11-01","12-25","12-26"].forEach(md => set.add(`${year}-${md}`));
  // Mariä Himmelfahrt (15.08.) – regional in Bayern, hier pauschal als „Bayern“ geführt
  set.add(`${year}-08-15`);
  // Bewegliche Feiertage (über Ostern)
  set.add(formatYMD(addDaysUTC(easter, -2)));  // Karfreitag
  set.add(formatYMD(addDaysUTC(easter, 1)));   // Ostermontag
  set.add(formatYMD(addDaysUTC(easter, 39)));  // Christi Himmelfahrt
  set.add(formatYMD(addDaysUTC(easter, 50)));  // Pfingstmontag
  set.add(formatYMD(addDaysUTC(easter, 60)));  // Fronleichnam
  return set;
}
function countBavariaHolidaysBetween(from, to){
  // Iteration: [from, to) (to exklusiv) passend zu daysBetween()
  if(!from || !to) return 0;
  const start = new Date(from + "T00:00:00Z");
  const end = new Date(to + "T00:00:00Z");
  if(!(start < end)) return 0;
  let count = 0;
  let cur = new Date(start.getTime());
  while(cur < end){
    const y = cur.getUTCFullYear();
    const hol = bavariaHolidaysSet(y);
    if(hol.has(formatYMD(cur))) count++;
    cur = addDaysUTC(cur, 1);
  }
  return count;
}
function countSundaysBetween(from, to){
  // [from, to) (to exklusiv) – passend zu daysBetween()
  if(!from || !to) return 0;
  const start = new Date(from + "T00:00:00Z");
  const end = new Date(to + "T00:00:00Z");
  if(!(start < end)) return 0;
  let count = 0;
  let cur = new Date(start.getTime());
  while(cur < end){
    // 0 = Sonntag
    if(cur.getUTCDay() === 0) count++;
    cur = addDaysUTC(cur, 1);
  }
  return count;
}
function updateAutoHolidayFields(){
  if(!currentDoc) return;
  const t = getTemplate(currentDoc.templateId);
  if(!t || t.id !== "hundeannahme") return;
  const from = currentDoc.meta?.von;
  const to = currentDoc.meta?.bis;
  const cnt = (from && to) ? countBavariaHolidaysBetween(from, to) : 0;
  const sundays = (from && to) ? countSundaysBetween(from, to) : 0;
  // Default: Sonn- & Feiertagszuschlag ist aktiv (kann im Aufenthalt deaktiviert werden)
  currentDoc.fields = currentDoc.fields || {};
  if(typeof currentDoc.fields.sun_hol_apply !== "boolean") currentDoc.fields.sun_hol_apply = true;
  // Immer automatisch – Anzahl wird berechnet; bei Deaktivierung = 0
  const sunHolApply = (currentDoc.fields.sun_hol_apply !== false);
  currentDoc.fields.holiday_days = sunHolApply ? (cnt || 0) : 0;
  currentDoc.fields.sunday_days  = sunHolApply ? (sundays || 0) : 0;
  // UI: Anzahl-Feld (falls vorhanden) befüllen & sperren
  const num = document.querySelector('input[data-key="holiday_days"]');
  if(num){
    num.value = String(currentDoc.fields.holiday_days || 0);
    num.disabled = true;
  }
  const numS = document.querySelector('input[data-key="sunday_days"]');
  if(numS){
    numS.value = String(currentDoc.fields.sunday_days || 0);
    numS.disabled = true;
  }
  // UI: Checkbox spiegeln
  const cbSunHol = document.querySelector('input[type="checkbox"][data-key="sun_hol_apply"]');
  if(cbSunHol) cbSunHol.checked = !!currentDoc.fields.sun_hol_apply;
  // Defaults für zählbasierte Zuschläge
  const days = daysBetween(from, to);
  // Standardmäßig sind (zähl-/zählbar) Zuschläge im Aufenthalt aktiv, können aber pro Aufenthalt deaktiviert werden.
  if(typeof currentDoc.fields.walks_enabled !== 'boolean') currentDoc.fields.walks_enabled = true;
  if(typeof currentDoc.fields.bandage_enabled !== 'boolean') currentDoc.fields.bandage_enabled = true;
  if(typeof currentDoc.fields.grooming_enabled !== 'boolean') currentDoc.fields.grooming_enabled = true;
  if(typeof currentDoc.fields.hygiene_enabled !== 'boolean') currentDoc.fields.hygiene_enabled = true;
  if(typeof currentDoc.fields.pickup_dropoff_enabled !== 'boolean') currentDoc.fields.pickup_dropoff_enabled = true;
  if(typeof currentDoc.fields.discount_enabled !== 'boolean') currentDoc.fields.discount_enabled = false;
  // Dauermedikation beim Hund -> im Aufenthalt automatisch vorauswählen
  try{
    if(currentDoc.fields.medication === undefined){
      const pet = getPetByDoc(currentDoc);
      const pid = pet?.id;
      const hasActivePlan = !!(pid && state?.medication?.plans && state.medication.plans.some(p => p.petId === pid && (p.active !== false)));
      if(hasActivePlan){
        currentDoc.fields.medication = true;
        const cb = document.querySelector('input[type="checkbox"][data-key="medication"]');
        if(cb) cb.checked = true;
      }
    }
  }catch(e){ /* noop */ }
  // Zusatz-Spaziergang: default Stückzahl = Aufenthaltstage (kann geändert oder auf 0 gesetzt werden)
  // Wir merken uns, ob der Wert automatisch gesetzt wurde, damit er bei Datumsänderungen mitwandert.
  const walkKey = 'walk_extra_count';
  const autoKey = 'walk_extra_auto';
  const curWalk = currentDoc.fields[walkKey];
  if(curWalk === undefined || curWalk === null || String(curWalk) === ''){
    currentDoc.fields[walkKey] = days;
    currentDoc.fields[autoKey] = true;
    const inp = document.querySelector(`input[data-key="${walkKey}"]`);
    if(inp) inp.value = String(days);
  }else{
    // Wenn der Nutzer den Wert verändert (≠ days), Auto-Modus deaktivieren.
    if(currentDoc.fields[autoKey] === true){
      const n = Number(curWalk);
      if(!Number.isFinite(n) || n !== days){
        currentDoc.fields[autoKey] = false;
      }else{
        // Auto aktiv und unverändert -> an neue Tage anpassen
        currentDoc.fields[walkKey] = days;
        const inp = document.querySelector(`input[data-key="${walkKey}"]`);
        if(inp) inp.value = String(days);
      }
    }
  }
  // Wenn per Aufenthalt deaktiviert, Werte auf 0 setzen und Eingaben sperren.
  try{
    const walkInp = document.querySelector(`input[data-key="${walkKey}"]`);
    if(currentDoc.fields.walks_enabled === false){
      currentDoc.fields[walkKey] = 0;
      currentDoc.fields[autoKey] = false;
      if(walkInp){ walkInp.value = '0'; walkInp.disabled = true; }
    }else{
      if(walkInp) walkInp.disabled = false;
    }
    const _lockCount = (flagKey, countKey)=>{
      const inp = document.querySelector(`input[data-key="${countKey}"]`);
      if(!inp) return;
      if(currentDoc.fields[flagKey] === false){
        currentDoc.fields[countKey] = 0;
        inp.value = '0';
        inp.disabled = true;
      }else{
        inp.disabled = false;
      }
    };
    _lockCount('bandage_enabled','bandage_count');
    _lockCount('grooming_enabled','grooming_count');
    _lockCount('hygiene_enabled','hygiene_days');
    _lockCount('pickup_dropoff_enabled','pickup_dropoff_count');
  }catch(_e){ /* noop */ }
  // Legacy-Key-Migration: alte Keys in neue Keys überführen (falls vorhanden)
  if(currentDoc.fields.extra_walk_count !== undefined && currentDoc.fields[walkKey] === undefined){
    currentDoc.fields[walkKey] = currentDoc.fields.extra_walk_count;
  }
  if(currentDoc.fields.bandage_change_count !== undefined && currentDoc.fields.bandage_count === undefined){
    currentDoc.fields.bandage_count = currentDoc.fields.bandage_change_count;
  }
  if(currentDoc.fields.grooming_extra_count !== undefined && currentDoc.fields.grooming_count === undefined){
    currentDoc.fields.grooming_count = currentDoc.fields.grooming_extra_count;
  }
}
function normalizeBetreuung(type){
  if(!type) return type;
  const s = String(type).trim();
  const l = s.toLowerCase();
  if(l === "urlaubsbetreuung") return "Urlaubsbetreuung";
  if(l === "tagesbetreuung") return "Tagesbetreuung";
  // allow already-normalized values
  return s;
}
function getPricePerDay(type, days){
  const rulesMap = (getPricingSettings().rules || PRICE_RULES_DEFAULT);
  const rules = rulesMap[type] || [];
  for(const r of rules){
    if(days >= r.min) return r.price;
  }
  return 0;
}
// ===== 4C-1: Preisvorschau im Aufenthalt (Brutto/Netto/MwSt) =====
function formatEuro(n){
  const v = Number(n||0);
  return v.toFixed(2).replace(".", ",") + " €";
}
function computeNetVatFromGross(gross, vatRate){
  const g = Number(gross||0);
  const r = Number(vatRate||0);
  if(!(r>0)) return { net: round2(g), vat: 0, gross: round2(g), rate: r };
  const net = g / (1 + r/100);
  const vat = g - net;
  return { net: round2(net), vat: round2(vat), gross: round2(g), rate: r };
}
function renderStayPricingPreview(docObj){
  try{
    const root = document.getElementById("formRoot");
    if(!root) return;
    if(!docObj || docObj.templateId !== "hundeannahme") return;
    // Pricing berechnen (setzt docObj.pricing)
    const pricing = calculateInvoicePricing(docObj);
    if(!pricing){
      // Falls Pflicht-Meta fehlt: keine Karte zeigen
      return;
    }
    const cfg = getPricingSettings();
    const vatRate = Number((state && state.settings && state.settings.vatRate) ?? cfg.vatPercent ?? 19) || 0;
    const nv = computeNetVatFromGross(pricing.total, vatRate);
    const card = document.createElement("div");
    card.className = "card";
    const percentLines = (pricing.percentItems||[]).map(it=>`<tr><td>${escapeHtml(it.label)}</td><td class="right">${it.rate>0?"+":""}${it.rate}%</td><td class="right">${formatEuro(it.value)}</td></tr>`).join("");
    const fixedLines = (pricing.fixedItems||[]).map(it=>{
      const qty = Number(it.qty||0);
      const unit = Number(it.unit||0);
      return `<tr><td>${escapeHtml(it.label)} (${qty}×${formatEuro(unit)})</td><td></td><td class="right">${formatEuro(it.value)}</td></tr>`;
    }).join("");
    card.innerHTML = `
      <h2>Preisübersicht (Vorschau)</h2>
      <p class="muted">Alle Preise sind <b>Brutto</b>. MwSt wird enthalten ausgewiesen.</p>
      <div class="row" style="gap:12px; flex-wrap:wrap;">
        <div style="min-width:220px;">
          <div class="muted">Betreuung / Tage</div>
          <div><b>${escapeHtml(pricing.betreuungNorm)}</b> – ${pricing.days} Tage × ${formatEuro(pricing.daily)}</div>
        </div>
        <div style="min-width:220px;">
          <div class="muted">Brutto gesamt</div>
          <div style="font-size:18px;"><b>${formatEuro(pricing.total)}</b></div>
          <div class="muted">Netto ${formatEuro(nv.net)} · MwSt (${vatRate}%) ${formatEuro(nv.vat)}</div>
        </div>
      </div>
      <div style="margin-top:10px; overflow:auto;">
        <table class="table" style="min-width:520px;">
          <thead><tr><th>Position</th><th class="right">Rate</th><th class="right">Betrag</th></tr></thead>
          <tbody>
            <tr><td>Grundpreis</td><td></td><td class="right">${formatEuro(pricing.base)}</td></tr>
            <tr><td>Sonn-/Feiertage (${pricing.sunHolDays} Tage)</td><td class="right">${pricing.sunHolRate}%</td><td class="right">${formatEuro(pricing.holidayValue)}</td></tr>
            ${percentLines}
            ${fixedLines}
            <tr><td colspan="2"><b>Gesamt (Brutto)</b></td><td class="right"><b>${formatEuro(pricing.total)}</b></td></tr>
          </tbody>
        </table>
      </div>
    `;
    // Karte VOR der Unterschrift einfügen (ganz am Ende, aber vor letzter card falls signature card existiert)
    const cards = root.querySelectorAll(".card");
    if(cards && cards.length){
      // Signature card ist i.d.R. die letzte. Wir hängen davor ein.
      const last = cards[cards.length-1];
      root.insertBefore(card, last);
    }else{
      root.appendChild(card);
    }
  }catch(e){
    console.warn("renderStayPricingPreview failed", e);
  }
}
// ===== END 4C-1 =====
function calculateInvoicePricing(doc){
  const meta = doc.meta || {};
  const f = doc.fields || {};
  if(!meta.betreuung || !meta.von || !meta.bis){
    return null;
  }
  const days = daysBetween(meta.von, meta.bis);
  const betreuungNorm = normalizeBetreuung(meta.betreuung);
  const daily = getPricePerDay(betreuungNorm, days);
  const base = days * daily;
  // Sonn- & Feiertags-Zuschlag (Standard: an)
  const cfg = getPricingSettings();
  const holidayDays = countBavariaHolidaysBetween(meta.von, meta.bis);
  const sundayDays = countSundaysBetween(meta.von, meta.bis);
  const sunHolApply = (f.sun_hol_apply !== false);
  const sunHolRate = Number((cfg.holidayPercent ?? cfg.sundayPercent ?? 0) || 0);
  const sunHolDays = sunHolApply ? (holidayDays + sundayDays) : 0;
  const sunHolUnit = round2(daily * (sunHolRate/100));
  const holidayValue = round2(sunHolDays * sunHolUnit);
  let percentExtra = 0;
  let fixedExtra = 0;
  const percentItems = [];
  // Prozent-Aufschläge (auf Basisbetrag)
  if(f.special_times){
    const r = (cfg.extras?.specialTimesPercent ?? 10);
    percentExtra += r;
    percentItems.push({ key:'special_times', label:`Sonderzeiten / Sonderaufwand`, rate: r, base: round2(base), value: round2(base * (r/100)) });
  }
  if(f.extra_care){
    const r = (cfg.extras?.extraCarePercent ?? 10);
    percentExtra += r;
    percentItems.push({ key:'extra_care', label:`Besondere Betreuung`, rate: r, base: round2(base), value: round2(base * (r/100)) });
  }
  // Sonntage/Feiertage sind über "sun_hol_apply" im Sonn-&Feiertagsblock abgedeckt.
  if(f.short_notice){
    const r = (cfg.extras?.shortNoticePercent ?? 0);
    if(r){
      percentExtra += r;
      percentItems.push({ key:'short_notice', label:`Kurzfristig`, rate: r, base: round2(base), value: round2(base * (r/100)) });
    }
  }
  // Sonderrabatt (%). Beispiel: 10 = -10% auf Basisbetrag
  if(f.discount_enabled !== false && String(f.discount_percent ?? '').trim() !== ''){
    const r = Number(f.discount_percent || 0);
    if(r){
      percentExtra -= r;
      percentItems.push({ key:'discount_percent', label:`Sonderrabatt`, rate: -r, base: round2(base), value: round2(base * (-r/100)) });
    }
  }
  // Summe Prozent-Wert (kann negativ sein bei Rabatt)
  const percentValue = round2(base * (percentExtra / 100));
  // Fixe Extras
  const fixedItems = [];
  if(!!f.medication){
    const qty = days;
    const unit = Number(cfg.extras?.medicationPerDay ?? 2);
    const v = qty * unit;
    fixedExtra += v;
    fixedItems.push({ key:'medication', label:`Medikamentengabe`, qty, unit, value: round2(v) });
  }
  if(f.walks_enabled !== false && f.walk_extra_count){
    const qty = Number(f.walk_extra_count||0);
    const unit = Number(cfg.extras?.walkExtraPrice ?? 15);
    const v = qty * unit;
    fixedExtra += v;
    fixedItems.push({ key:'walk_extra_count', label:`Zusatz-Spaziergänge`, qty, unit, value: round2(v) });
  }
  if(f.bandage_enabled !== false && f.bandage_count){
    const qty = Number(f.bandage_count||0);
    const unit = Number(cfg.extras?.bandagePrice ?? 2.5);
    const v = qty * unit;
    fixedExtra += v;
    fixedItems.push({ key:'bandage_count', label:`Verbandwechsel`, qty, unit, value: round2(v) });
  }
  if(f.grooming_enabled !== false && f.grooming_count){
    const qty = Number(f.grooming_count||0);
    const unit = Number(cfg.extras?.groomingPrice ?? 5);
    const v = qty * unit;
    fixedExtra += v;
    fixedItems.push({ key:'grooming_count', label:`Pflege/Extra`, qty, unit, value: round2(v) });
  }
  // optionale fixe Zuschläge
  if(f.hygiene_enabled !== false && f.hygiene_days){
    const qty = Number(f.hygiene_days||0);
    const unit = Number(cfg.extras?.hygienePerDay ?? 0);
    const v = qty * unit;
    if(v){
      fixedExtra += v;
      fixedItems.push({ key:'hygiene_days', label:`Hygiene/Extra`, qty, unit, value: round2(v) });
    }
  }
  if(f.pickup_dropoff_enabled !== false && f.pickup_dropoff_count){
    const qty = Number(f.pickup_dropoff_count||0);
    const unit = Number(cfg.extras?.pickupDropoffPrice ?? 0);
    const v = qty * unit;
    if(v){
      fixedExtra += v;
      fixedItems.push({ key:'pickup_dropoff_count', label:`Abhol-/Bringservice`, qty, unit, value: round2(v) });
    }
  }
  fixedExtra = Math.round(fixedExtra * 100) / 100;
  // Alle Preise sind BRUTTO. total = zahlbarer Bruttobetrag.
  const total = round2(base + holidayValue + percentValue + fixedExtra);
  doc.pricing = {
    days,
    daily,
    betreuungNorm,
    base,
    holidayDays,
    sundayDays,
    sunHolDays,
    sunHolRate,
    sunHolUnit,
    holidayValue,
    percentExtra,
    percentValue,
    percentItems,
    fixedExtra,
    fixedItems,
    total
  };
  return doc.pricing;
}
// ===== 3A: Rechnungspreise aus Aufenthalt ableiten =====
// Mapping: Aufenthalt.pricing -> Invoice.pricing (Basis + Zuschläge)
// Hinweis: Feiertagszuschlag wird als eigener Wert berechnet und in percentExtra (Wert) mitgeführt,
// damit die Rechnung bereits den korrekten Gesamtbetrag enthält, ohne das UI sofort zu erweitern.
function round2(n){ return Math.round((Number(n)||0) * 100) / 100; }
function recomputeInvoiceTotals(inv){
  inv.pricing = inv.pricing || {};
  inv.pricing.parts = inv.pricing.parts || {};
  const parts = inv.pricing.parts;
  // 3E-4: Zuschläge werden im Aufenthalt gesteuert.
  // In der Rechnung werden die übernommenen Teile immer voll angewandt.
  const base   = Number(parts.base||0);
  const hol    = Number(parts.holiday||0);
  const perc   = Number(parts.percent||0);
  const fixed  = Number(parts.fixed||0);
  inv.pricing.applied = { holiday: round2(hol), percent: round2(perc), fixed: round2(fixed) };
  // Alle Preise sind BRUTTO. MwSt wird als "enthalten" ausgewiesen.
  const gross = round2(base + hol + perc + fixed);
  const cfg = getPricingSettings();
  const settingsVat = Number((state && state.settings && state.settings.vatRate) ?? cfg.vatPercent ?? 19) || 0;
  const vatRate = (typeof inv.vatRate === 'number' && !Number.isNaN(inv.vatRate)) ? inv.vatRate : settingsVat;
  inv.vatRate = vatRate;
  const net = vatRate > 0 ? (gross / (1 + vatRate/100)) : gross;
  const vatAmount = gross - net;
  inv.pricing.net = round2(net);
  inv.pricing.vatAmount = round2(vatAmount);
  inv.pricing.total = round2(gross); // zahlbarer Bruttobetrag
  inv.pricing.totalNet = inv.pricing.net;
  inv.pricing.totalGross = inv.pricing.total;
}
async function updateInvoiceAfterEdit(inv){
  // Persist to state + storage
  state.invoices = state.invoices || {};
  state.invoices[inv.id] = inv;
  saveState();
  // Refresh list + open detail again
  renderInvoices();
  openInvoice(inv.id);
}
window.toggleInvoiceExtra = async function(invoiceId, key, checked){
  const inv = (state.invoices||{})[invoiceId];
  if (!inv) return;
  if (inv.pricing && inv.pricing.locked) return;
  inv.pricing = inv.pricing || {};
  inv.pricing.flags = inv.pricing.flags || {};
  inv.pricing.flags[key] = !!checked;
  recomputeInvoiceTotals(inv);
  // 4C-2: Line-Items + Meta-Snapshot für revisionssichere Rechnung
  try{ inv.lineItems = buildInvoiceLineItems(inv); inv.lineItemsUpdatedAt = new Date().toISOString(); }catch(_){ }
  try{ snapshotInvoiceSourceMeta(inv); }catch(_){ }
  await updateInvoiceAfterEdit(inv);
};
window.setInvoiceVatRate = async function(invoiceId, value){
  const inv = (state.invoices||{})[invoiceId];
  if (!inv) return;
  if (inv.pricing && inv.pricing.locked) return;
  const v = Number(value);
  inv.vatRate = (Number.isFinite(v) && v >= 0) ? v : 0;
  recomputeInvoiceTotals(inv);
  await updateInvoiceAfterEdit(inv);
};
function syncInvoicePricingFromDoc(inv, doc){
  if(!inv || !doc) return false;
  const p = calculateInvoicePricing(doc);
  if(!p) return false;
  inv.pricing = inv.pricing || { basePrice:0, percentExtra:0, fixedExtra:0, total:0 };
  const basePrice = round2(p.base || 0);
  const percentRate = round2(p.percentExtra || 0);         // %
  const percentValue = round2(p.percentValue || 0);        // €
  const holidayDays = Number(p.sunHolDays || 0);           // Sonn + Feiertage
  const holidayExtra = round2(p.holidayValue || 0);        // € (Sonn-/Feiertag)
  const fixedExtra = round2(p.fixedExtra || 0);            // €
  const fixedItems = Array.isArray(p.fixedItems) ? p.fixedItems : [];
  const percentItems = Array.isArray(p.percentItems) ? p.percentItems : [];
  const total = round2(basePrice + percentValue + holidayExtra + fixedExtra);
  const changed =
    round2(inv.pricing.basePrice) !== basePrice ||
    round2(inv.pricing.percentExtra) !== percentValue ||
    round2(inv.pricing.fixedExtra) !== fixedExtra ||
    round2(inv.pricing.total) !== total ||
    round2(inv.pricing.holidayExtra||0) !== holidayExtra ||
    Number(inv.pricing.holidayDays||0) !== holidayDays ||
    round2(inv.pricing.percentRate||0) !== percentRate;
  inv.pricing.basePrice = basePrice;
  // UI/PDF: Prozent-Zuschlag ohne Feiertage (Feiertage separat)
  inv.pricing.percentExtra = percentValue;   // €-Wert (nur Prozent-Aufschläge)
  inv.pricing.percentRate = percentRate;     // %-Summe (z.B. 10/20)
  // Feiertage separat aufschlüsseln
  inv.pricing.holidayDays = holidayDays;
  inv.pricing.holidayExtra = holidayExtra;
  inv.pricing.fixedExtra = fixedExtra;
  // 3E: Detail-Breakdown für Anzeige/PDF
  inv.pricing.breakdown = {
    percentItems: percentItems,
    fixedItems: fixedItems
  };
  // canonical parts + totals (supports toggles + MwSt)
  inv.pricing.parts = { base: basePrice, percent: percentValue, holiday: holidayExtra, fixed: fixedExtra };
  // 3E: Detail-Aufschlüsselung für UI/PDF
  inv.pricing.breakdown = {
    percentItems: percentItems,
    fixedItems: fixedItems,
    holidayDays: holidayDays,
    sunHolDays: holidayDays,
    sunHolRate: Number(p.sunHolRate||0),
    sunHolUnit: Number(p.sunHolUnit||0)
  };
  recomputeInvoiceTotals(inv);
  // Zusatzinfos (harmless, falls später gebraucht)
  inv.pricing._calc = {
    days: p.days,
    daily: p.daily,
    betreuungNorm: p.betreuungNorm,
    percentRate: percentRate,
    percentValue: percentValue,
    holidayDays: holidayDays,
    holidayExtra: holidayExtra
    ,percentItems: percentItems
    ,fixedItems: fixedItems
  };
  // Zeitraum aus Aufenthalt synchron halten (falls nachträglich geändert)
  try{
    inv.period = inv.period || {};
    if(doc?.meta?.von) inv.period.from = doc.meta.von;
    if(doc?.meta?.bis) inv.period.to = doc.meta.bis;
  }catch(_){}
  if(changed){
    inv.updatedAt = new Date().toISOString();
  }
  return changed;
}
function isInvoicePricingLocked(inv){
  if(!inv) return false;
  return inv.pricingLocked === true || !!inv.pricingLockedAt || !!inv.pricingSnapshot;
}
function shouldFreezeInvoice(inv){
  const s = String(inv?.status||'').toLowerCase();
  // 3D4/3E: Einfrieren erst bei "bezahlt" (Storno bleibt editierbar, falls nötig)
  return (s==='paid') && isInvoicePricingLocked(inv);
}
function getInvoiceSourceDoc(inv){
  if(!inv || !inv.sourceDocId) return null;
  return (state.docs||[]).find(d=>d.id===inv.sourceDocId) || (state.stays||[]).find(d=>d.id===inv.sourceDocId) || null;
}
function syncInvoicePricingBySource(inv){
  if(!inv || !inv.sourceDocId) return false;
  // 3C: Wenn Rechnung eingefroren ist (Status offen/bezahlt/storniert), niemals neu berechnen.
  if(shouldFreezeInvoice(inv)){
    // safety: restore snapshot if present
    if(inv.pricingSnapshot){
      inv.pricing = JSON.parse(JSON.stringify(inv.pricingSnapshot));
    }
    if(inv.lineItemsSnapshot){
      inv.lineItems = JSON.parse(JSON.stringify(inv.lineItemsSnapshot));
    }
    if(inv.sourceSnapshotAtLock){
      inv.sourceSnapshot = JSON.parse(JSON.stringify(inv.sourceSnapshotAtLock));
    }
    return false;
  }
  const doc = getInvoiceSourceDoc(inv);
  if(!doc) return false;
  return syncInvoicePricingFromDoc(inv, doc);
}
// Batch sync before rendering lists (keeps UI totals correct)
function syncAllInvoicePricingGuarded(){
  try{
    if(!Array.isArray(state.invoices)) return;
    let any = false;
    for(const inv of state.invoices){
      if(inv && inv.sourceDocId){
        const changed = syncInvoicePricingBySource(inv);
        if(changed) any = true;
      }
    }
    if(any) saveState();
  }catch(e){
    console.warn("syncAllInvoicePricingGuarded failed", e);
  }
}
// ===== /3A =====
// ===== ENDE PREISLOGIK =====
