        return `<tr><td>${escapeHtml(formatDateDE(r.date))}</td><td>${escapeHtml(r.time||"")}</td><td>${escapeHtml(dog)}</td><td>${escapeHtml(med)}</td><td>${escapeHtml(st)}</td><td>${escapeHtml(r.reason||"")}</td><td>${escapeHtml(by)}</td></tr>`;
