        return `<tr><td>${escapeHtml(formatDateDE(n.date))}</td><td>${escapeHtml(dog)}</td><td>${tags}</td><td>${escapeHtml(n.text||"")}</td><td>${escapeHtml(flags)}</td><td>${escapeHtml(by)}</td></tr>`;
