function buildCanonicalCustomerList(){
  const list = [];
  const seen = new Set();
  const normalize = (v='')=>String(v||'').trim().toLowerCase();
  const add = (raw={})=>{
    if(!raw || typeof raw !== 'object') return;
    const firstName = String(raw.firstName || raw.firstname || '').trim();
    const lastName = String(raw.lastName || raw.lastname || '').trim();
    const combinedName = [firstName, lastName].filter(Boolean).join(' ').trim();
    const id = String(raw.id || raw.customerId || raw.uid || raw.portalUid || raw.key || raw.email || raw.name || raw.fullName || combinedName || '').trim();
    const customerId = String(raw.customerId || raw.id || raw.uid || raw.portalUid || raw.key || raw.email || raw.name || raw.fullName || combinedName || '').trim();
    const name = String(raw.name || raw.displayName || raw.customerName || raw.ownerName || raw.owner || raw.fullName || combinedName || '').trim();
    const email = String(raw.email || raw.mail || '').trim();
    const phone = String(raw.phone || raw.telefon || raw.mobile || raw.tel || '').trim();
    const portalUid = String(raw.portalUid || raw.portalUID || raw.userUid || raw.customerUid || raw.uid || '').trim();
    if(!id && !customerId && !name && !email && !phone) return;
    const label = name || email || phone || customerId || id || 'Kunde';
    const key = String(email || portalUid || customerId || id || label).toLowerCase();
    if(!key || seen.has(key)) return;
    seen.add(key);
    list.push({
      id: id || customerId || email || label,
      customerId: customerId || id || email || label,
      name: String(label).trim(),
      email,
      phone,
      portalUid
    });
  };

  (Array.isArray(state.customers) ? state.customers : []).forEach(add);

  try{
    const pets = Array.isArray(state.pets) ? state.pets : [];
    pets.forEach(p=>{
      if(!p) return;
      if(p.customerId){
        const c = getCustomer(p.customerId);
        if(c) add(c);
      }
      add({
        id: p.customerId || p.ownerId || '',
        customerId: p.customerId || p.ownerId || '',
        name: p.ownerName || p.owner || '',
        phone: p.ownerPhone || p.phone || '',
        email: p.ownerEmail || p.email || ''
      });
    });
  }catch(_){ }

  try{
    const sel = document.getElementById('customerSelect');
    if(sel && sel.options && sel.options.length){
      Array.from(sel.options).forEach(opt=>{
        const value = String(opt.value || '').trim();
        const text = String(opt.textContent || '').trim();
        if(!value || !text || /^\(?kunde w[aä]hlen\)?$/i.test(text) || /^bitte ausw[aä]hlen/i.test(text)) return;
        const parts = text.split(' · ').map(x=>String(x||'').trim()).filter(Boolean);
        add({ id: value, customerId: value, name: parts[0] || text, phone: parts[1] || '' });
      });
    }
  }catch(_){ }

  try{
    const dogList = document.getElementById('dogList');
    const customers = Array.isArray(state.customers) ? state.customers : [];
    if(dogList){
      Array.from(dogList.querySelectorAll('.item')).forEach(item=>{
        const strong = item.querySelector('strong');
        if(!strong) return;
        const rawText = String(strong.textContent || '').replace(/\s+/g, ' ').trim();
        if(!rawText) return;
        if(/^🐶/.test(rawText)) return;
        let name = rawText
          .replace(/^[^\p{L}\p{N}]+/u, '')
          .replace(/^Ohne Kunde verknüpft$/i, '')
          .trim();
        if(!name) return;
        const small = item.querySelector('small');
        const smallText = String(small?.textContent || '').trim();
        const bits = smallText.split('·').map(x=>String(x||'').trim()).filter(Boolean);
        const phoneOrMail = bits.find(x=>!/(^\d+\s+Hund(e)?$)|(^Letzter Aufenthalt:)/i.test(x)) || '';
        const isMail = /@/.test(phoneOrMail);
        const existing = customers.find(c=>normalize(c.name)===normalize(name) || (!!phoneOrMail && (normalize(c.phone)===normalize(phoneOrMail) || normalize(c.email)===normalize(phoneOrMail))));
        add({
          id: existing?.id || existing?.customerId || existing?.email || `dom:${name}|${phoneOrMail}`,
          customerId: existing?.customerId || existing?.id || existing?.email || `dom:${name}|${phoneOrMail}`,
          name: existing?.name || name,
          phone: existing?.phone || (isMail ? '' : phoneOrMail),
          email: existing?.email || (isMail ? phoneOrMail : '')
        });
      });
    }
  }catch(_){ }

  try{
    const customerItems = Array.from(document.querySelectorAll('#dogList .item strong, [data-tab-panel="dogs"] .item strong, #tab-dogs .item strong'));
    customerItems.forEach(strong=>{
      const rawText = String(strong.textContent || '').replace(/\s+/g, ' ').trim();
      if(!rawText || /^🐶/.test(rawText)) return;
      const name = rawText.replace(/^[^\p{L}\p{N}]+/u, '').trim();
      if(!name || /^ohne kunde/i.test(name)) return;
      const item = strong.closest('.item');
      const smalls = Array.from(item?.querySelectorAll('small') || []);
      const smallText = smalls.map(s=>String(s.textContent || '').trim()).join(' · ');
      const bits = smallText.split('·').map(x=>String(x||'').trim()).filter(Boolean);
      const phoneOrMail = bits.find(x=>!/(^\d+\s+Hund(e)?$)|(^Letzter Aufenthalt:)/i.test(x)) || '';
      add({
        id: `render:${name}|${phoneOrMail}`,
        customerId: `render:${name}|${phoneOrMail}`,
        name,
        phone: /@/.test(phoneOrMail) ? '' : phoneOrMail,
        email: /@/.test(phoneOrMail) ? phoneOrMail : ''
      });
    });
  }catch(_){ }

  return list.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''), 'de'));
}
function refreshCustomerSelect(){
  const sel = document.getElementById("customerSelect");
  if(!sel) return;
  const customers = buildCanonicalCustomerList();
  sel.innerHTML = customers.map(c=>`<option value="${escapeHtml(c.customerId||c.id)}">${escapeHtml(c.name||"Kunde")}${(c.email||c.phone)?(" · "+escapeHtml(c.email||c.phone)):""}</option>`).join("");
}
