  const chipSelect = String(document.getElementById('p_chipStatus')?.value || '');
  if(!customerName){ cpSetStatus('Bitte Kundennamen eintragen.', true); try{ alert('Bitte Kundennamen eintragen.'); }catch(_){ } return false; }
