function dsOpenProposalInCustomerEditor(row, opts){
  opts = opts || {};
  try{
    row = dsEnrichProposalReviewRow(row);
    dsEnsureReviewStyles();
    dsClearProposalReviewUI();
    ensureStateShape();
    const payload = row && (row.payloadSubmitted || row.payloadDraft || row.payload || row.data || {}) || {};
    const customerPayload = (payload && payload.customer && typeof payload.customer === 'object') ? payload.customer : (row && row.customer && typeof row.customer === 'object' ? row.customer : {});
    const petPayload = (payload && payload.pet && typeof payload.pet === 'object') ? payload.pet : (row && row.pet && typeof row.pet === 'object' ? row.pet : {});
    const isCustomerProposal = String((row && (row.templateId || row.proposalType || row.kind || row.formKey)) || '').toLowerCase().includes('customer')
      || String((payload && payload.source) || '').toLowerCase().includes('customer-main-dogs')
      || !!(customerPayload && Object.keys(customerPayload).length)
      || !!(petPayload && Object.keys(petPayload).length);
    if(!isCustomerProposal || (!Object.keys(customerPayload).length && !Object.keys(petPayload).length)) return false;

    try{ dsSetProposalOpenDiag('entry row=' + String((row && (row.id || row.proposalId || row.taskId)) || '--') + ' cid=' + String((row && (row.__targetCustomerId || row.customerId)) || '--') + ' pid=' + String((row && (row.__targetPetId || row.petId)) || '--'), false); }catch(_){ }

    let directPetId = '';
    try{ directPetId = dsGetDirectProposalReviewPetId(row); }catch(_){ directPetId = ''; }
    const targets = dsResolveProposalReviewTargets(row);
    let baseCustomer = targets.customer || null;
    let basePet = targets.pet || null;
    let basePetId = String((directPetId || (basePet && (basePet.id || basePet.petId)) || (row && row.__targetPetId) || (row && row.petId) || '')).trim();
    if(!basePet && basePetId){ try{ basePet = (typeof getPet === 'function' ? getPet(basePetId) : null) || null; }catch(_){ } }
    if(!baseCustomer && basePet){ try{ baseCustomer = (typeof getCustomer === 'function' ? getCustomer(basePet.customerId || basePet.ownerId || '') : null) || null; }catch(_){ } }
    if((!baseCustomer || !basePet || !basePetId) && basePetId){
      try{
        const allPets = asArray(state && (((state.pets||[]).length ? state.pets : state.dogs) || []));
        const hitPet = allPets.find(function(x){ return norm((x && (x.id || x.petId || '')) || '') === norm(basePetId); }) || null;
        if(hitPet) basePet = basePet || hitPet;
        if(!baseCustomer && hitPet && typeof getCustomer === 'function') baseCustomer = getCustomer(hitPet.customerId || hitPet.ownerId || '') || null;
      }catch(_){ }
    }
    if((!baseCustomer || !basePet || !basePetId)){
      try{
        const customers = asArray(state && state.customers);
        const pets = asArray(state && (((state.pets||[]).length ? state.pets : state.dogs) || []));
        if(!baseCustomer && customers.length === 1) baseCustomer = customers[0] || null;
        if(!basePet && pets.length === 1) basePet = pets[0] || null;
        if(!baseCustomer && basePet && typeof getCustomer === 'function') baseCustomer = getCustomer(basePet.customerId || basePet.ownerId || '') || null;
        if(basePet && !basePetId) basePetId = String(basePet.id || basePet.petId || '');
      }catch(_){ }
    }
    if((!baseCustomer || !basePet || !basePetId)){
      try{
        if(typeof selectTab === 'function') selectTab('dogs');
        else if(typeof showPanel === 'function') showPanel('dogs');
        else dsForceShowPanel('dogs');
      }catch(_){ }
      try{ if(typeof renderDogs === 'function') renderDogs(); }catch(_){ }
      let uiPetId = '';
      try{ uiPetId = dsGetDirectProposalReviewPetId(row); }catch(_){ uiPetId = ''; }
      if(uiPetId){
        basePetId = String(uiPetId || '').trim();
        try{ if(typeof openCpEditor === 'function') openCpEditor('edit', basePetId); }catch(_){ }
        try{ basePet = basePet || (typeof getPet === 'function' ? getPet(basePetId) : null) || null; }catch(_){ }
        try{
          if(!baseCustomer){
            const ownerId = norm((basePet && (basePet.customerId || basePet.ownerId)) || (row && row.__targetCustomerId) || (row && row.customerId) || '');
            if(ownerId && typeof getCustomer === 'function') baseCustomer = getCustomer(ownerId) || null;
          }
        }catch(_){ }
      }
    }
    if(!baseCustomer || !basePet || !basePetId){
      try{ if(dsTryVisibleProposalButtonOpen(row, customerPayload, petPayload, opts)) return true; }catch(_){ }
      try{
        if(dsScheduleProposalReviewUiOpen(row, customerPayload, petPayload, opts)) return true;
      }catch(_){ }
      try{ cpSetStatus('Bestehender Kunde/Hund für Vorschlag nicht gefunden.', true); }catch(_){ }
      if(!opts.silent){
        try{
          const sig = String((row && row.__sourceKey) || dsInboxHandledKey(row) || row.id || '1');
          const now = Date.now();
          const prevSig = String(window.__dsProposalOpenAlertSig || '');
          const prevAt = Number(window.__dsProposalOpenAlertAt || 0);
          if(prevSig !== sig || (now - prevAt) > 1200){
            window.__dsProposalOpenAlertSig = sig;
            window.__dsProposalOpenAlertAt = now;
            alert('Bestehender Kunde/Hund für Vorschlag nicht eindeutig gefunden. Es wurde nichts geöffnet.');
          }
        }catch(_){ }
      }
      return false;
    }

    return dsFinalizeProposalReviewEditor(row, baseCustomer, basePet, basePetId, customerPayload, petPayload, opts);
  }catch(err){
    try{ window.__dsProposalReviewOpening = false; }catch(_){ }
    console.error('dsOpenProposalInCustomerEditor failed', err);
    return false;
  }
}

