  if(!doc) return;
  // nur bei Aufenthalten (hundeannahme)
  const isStay = (doc.templateId === "hundeannahme" || doc.templateName === "Aufenthalte" || doc.type === "stay");
  if(!isStay) return;
  const customerId = doc.customerId || "";
