/* ===== 4B-1 Rechtstexte Anzeige (Doc-Modal) ===== */
function _legalDocTitle(kind){
  const k = String(kind||'').toLowerCase();
  if(k==='agb') return 'AGB – Doggy Style Hundepension';
  if(k==='dsgvo') return 'Datenschutzhinweis (DSGVO) – Doggy Style Hundepension';
  if(k==='tierarzt') return 'Tierarzt-Erlaubnis / Notfall-Vollmacht';
  if(k==='wahrheit') return 'Erklärung – Angaben wahrheitsgemäß';
  return 'Dokument';
}
function _legalDocFilename(kind){
  const k = String(kind||'').toLowerCase();
  if(k==='agb') return 'AGB_DoggyStyle.pdf';
  if(k==='dsgvo') return 'Datenschutz_DSGVO_DoggyStyle.pdf';
  if(k==='tierarzt') return 'Tierarzt_Erlaubnis_DoggyStyle.pdf';
  if(k==='wahrheit') return 'Angaben_Wahrheitsgemaess_DoggyStyle.pdf';
  return 'Dokument.pdf';
}
function _legalToHtmlDoc(title, text){
  const safeTitle = escapeHtml(String(title||'Dokument'));
  const safeText = escapeHtml(String(text||''));
  return `<!doctype html>
<html lang="de"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${safeTitle}</title>
<style>
  body{font-family: -apple-system, system-ui, Segoe UI, Roboto, Arial, sans-serif; margin:24px; color:#111;}
  h1{font-size:20px; margin:0 0 14px 0;}
  pre{white-space:pre-wrap; line-height:1.35; font-size:14px; background:#f6f6f6; padding:14px; border-radius:12px; border:1px solid #e6e6e6;}
  .muted{color:#666; font-size:12px; margin-top:10px;}
</style>
</head><body>
<h1>${safeTitle}</h1>
<pre>${safeText}</pre>
<div class="muted">Hinweis: In der App „Drucken/Speichern“ nutzen, um als PDF zu sichern.</div>
</body></html>`;
}
function openLegalDoc(kind){
  try{
    const k = String(kind||'').toLowerCase();
    const title = _legalDocTitle(k);
    const text = getLegalText(k) || '';
    const html = _legalToHtmlDoc(title, text);
    const url = URL.createObjectURL(new Blob([html], {type:'text/html'}));
    openDocModal(url, title, null, _legalDocFilename(k));
  }catch(e){
    console.warn('openLegalDoc failed', e);
    alert('Dokument konnte nicht geöffnet werden.');
  }
}
document.addEventListener('DOMContentLoaded', ()=>{
  const w = (id, kind)=>{
    const el = document.getElementById(id);
    if(!el) return;
    el.addEventListener('click', (e)=>{ e.preventDefault(); openLegalDoc(kind); });
  };
  w('btnLegalDSGVO','dsgvo');
  w('btnLegalAGB','agb');
  w('btnLegalTierarzt','tierarzt');
  w('btnLegalWahrheit','wahrheit');
});
/* ===== END 4B-1 ===== */

// ===== DS_DIAG_OVERLAY (4F-4) =====
(function DS_DIAG_OVERLAY(){
  function safe(v){ try{ return (v===undefined||v===null) ? "" : String(v); }catch(_ ){ return ""; } }
  function getSWVer(){
    try{ return safe(window.SW_VERSION || window.__DS_SW_VERSION || ""); }catch(_ ){ return ""; }
  }
  function render(){
    try{
      const id="dsDiagOverlay";
      let el=document.getElementById(id);
      if(!el){
        el=document.createElement("div");
        el.id=id;
        el.style.position="fixed";
        el.style.right="10px";
        el.style.bottom="10px";
        el.style.zIndex="999999";
        el.style.maxWidth="86vw";
        el.style.fontSize="12px";
        el.style.lineHeight="1.25";
        el.style.padding="10px 12px";
        el.style.borderRadius="12px";
        el.style.background="rgba(0,0,0,0.65)";
        el.style.color="#fff";
        el.style.backdropFilter="blur(8px)";
        el.style.webkitBackdropFilter="blur(8px)";
        el.style.display="none";
        el.style.whiteSpace="pre-wrap";
        el.style.boxShadow="0 6px 18px rgba(0,0,0,0.25)";
        document.body.appendChild(el);
      }
      const BUILD = (typeof APP_BUILD!=='undefined')?APP_BUILD:"M50.2_BLUE_TEMPLATE_PRINT_CONTRACT_20260215";
      const meta = document.querySelector('meta[name="app-version"]');
      const htmlBuild = meta ? meta.getAttribute('content') : "";
      const online = navigator.onLine ? "online" : "offline";
      const swv = getSWVer();
      let cacheKeys="";
      try{
        cacheKeys = el.dataset.cacheKeys || "";
        if(window.caches && caches.keys && !cacheKeys){
          caches.keys().then(keys=>{
            try{ el.dataset.cacheKeys = keys.join(", "); }catch(_ ){}
            if(el.style.display!=="none") render();
          }).catch(()=>null);
        }
      }catch(_ ){}
      let lastSync = "";
      try{ lastSync = safe(localStorage.getItem("ds_last_sync")||localStorage.getItem("last_sync")||""); }catch(_ ){}
      el.textContent =
        "DIAG\n" +
        "Build(JS): " + BUILD + "\n" +
        "Build(HTML): " + safe(htmlBuild) + "\n" +
        "SW: " + safe(swv) + "\n" +
        "Net: " + online + "\n" +
        (lastSync?("LastSync: "+lastSync+"\n"):"") +
        (cacheKeys?("Caches: "+cacheKeys+"\n"):"") +
        "URL: " + location.pathname + location.search;
    }catch(_ ){}
  }
  function toggle(){
    try{
      const el=document.getElementById("dsDiagOverlay");
      if(!el) render();
      const e=document.getElementById("dsDiagOverlay");
      if(!e) return;
      e.style.display = (e.style.display==="none"||!e.style.display) ? "block" : "none";
      if(e.style.display!=="none") render();
    }catch(_ ){}
  }
  try{ window.__DS_DIAG_TOGGLE = toggle; }catch(_ ){}
  try{
    const bid="dsDiagBtn";
    let b=document.getElementById(bid);
    if(!b){
      b=document.createElement("button");
      b.id=bid;
      b.type="button";
      b.textContent="DIAG";
      b.style.position="fixed";
      b.style.right="10px";
      b.style.bottom="52px";
      b.style.zIndex="999999";
      b.style.padding="6px 10px";
      b.style.borderRadius="12px";
      b.style.border="1px solid rgba(255,255,255,0.25)";
      b.style.background="rgba(0,0,0,0.35)";
      b.style.color="#fff";
      b.style.fontSize="12px";
      b.style.backdropFilter="blur(8px)";
      b.style.webkitBackdropFilter="blur(8px)";
      b.addEventListener("click", toggle);
      if(document.body) document.body.appendChild(b);
      else document.addEventListener("DOMContentLoaded", ()=>{ try{ document.body.appendChild(b); }catch(_ ){} });
    }
  }catch(_ ){}
  try{
    if(document.readyState==="loading") document.addEventListener("DOMContentLoaded", render);
    else render();
    window.addEventListener("online", render);
    window.addEventListener("offline", render);
  }catch(_ ){}
})();
// ===== END DS_DIAG_OVERLAY =====


// ===== DS_HARD_RELOAD_BTN (4F-5) =====
async function dsHardReload(){
  try{
    const ok = confirm("App-Cache zurücksetzen und neu laden?\n\nDas löscht Service Worker + Cache (Offline-Daten bleiben i.d.R. erhalten).");
    if(!ok) return;
  }catch(_ ){}

  try{
    if('serviceWorker' in navigator){
      const regs = await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map(r=>r.unregister().catch(()=>null)));
    }
  }catch(_ ){}

  try{
    if(window.caches && caches.keys){
      const keys = await caches.keys();
      await Promise.all(keys.map(k=>caches.delete(k)));
    }
  }catch(_ ){}

  try{
    const toDelete = [];
    for(let i=0;i<localStorage.length;i++){
      const k = localStorage.key(i);
      if(!k) continue;
      if(k.startsWith('ds_') || k.includes('sw') || k.includes('cache') || k.includes('build') || k.includes('version')){
        toDelete.push(k);
      }
    }
    toDelete.forEach(k=>{ try{ localStorage.removeItem(k); }catch(_ ){} });
  }catch(_ ){}

  try{
    const url = new URL(location.href);
    url.searchParams.set('v', 'M39_4F5_HARD_RELOAD_BTN_20260207');
    location.replace(url.toString());
  }catch(_ ){ location.reload(); }
}

(function DS_HARD_RELOAD_BTN(){
  try{
    const bid="dsHardReloadBtn";
    if(document.getElementById(bid)) return;
    const b=document.createElement("button");
    b.id=bid;
    b.type="button";
    b.textContent="RESET";
    b.title="Service Worker + Cache zurücksetzen";
    b.style.position="fixed";
    b.style.right="10px";
    b.style.bottom="94px";
    b.style.zIndex="999999";
    b.style.padding="6px 10px";
    b.style.borderRadius="12px";
    b.style.border="1px solid rgba(255,255,255,0.25)";
    b.style.background="rgba(160,0,0,0.35)";
    b.style.color="#fff";
    b.style.fontSize="12px";
    b.style.backdropFilter="blur(8px)";
    b.style.webkitBackdropFilter="blur(8px)";
    b.addEventListener("click", ()=>{ dsHardReload(); });
    if(document.body) document.body.appendChild(b);
    else document.addEventListener("DOMContentLoaded", ()=>{ try{ document.body.appendChild(b); }catch(_ ){} });
  }catch(_ ){}
})();
