function renderStatisticsPanel(){
  const panel = document.getElementById('statistics');
  if(!panel) return;

  panel.innerHTML = `
    <div class="card" style="margin-top:10px;">
      <h1 style="margin:0 0 6px;">📈 Statistik</h1>
      <div class="muted" style="font-size:12px; line-height:1.35;">
        Forschungsmodus: standardisierte Erfassung (1–10), Kontextvariablen & reproduzierbarer Belastungsindex (Modell B) – exportierbar für R/Python/SPSS.
      </div>
      <div class="row" style="margin-top:10px; gap:8px; flex-wrap:wrap;">
        <button class="btn" id="statSub_capture">Erfassung</button>
        <button class="btn" id="statSub_analysis">Analyse</button>
        <button class="btn" id="statSub_export">Export</button>
        <button class="btn" id="statSub_ratings">Bewertungen</button>
        <button class="btn" id="statSub_method">Methodik</button>
      </div>
    </div>

    <div id="statSubBody" style="margin-top:10px;"></div>
  `;

  // bind
  const setActive = (k)=>{
    state.__statSub = k;

    // button states
    ['capture','analysis','export','ratings','method'].forEach(x=>{
      const b = document.getElementById('statSub_'+x);
      if(!b) return;
      b.classList.toggle('btn-primary', x===k);
      // keep base button styling
      if(x!==k) b.classList.remove('btn-primary');
    });

    const host = document.getElementById('statSubBody');
    if(host) host.innerHTML = '';

    const safeRender = (fn, label)=>{
      try{
        fn();
      }catch(err){
        try{ console.error('[STAT] Render-Fehler in', label, err); }catch(_){}
        if(host){
          const msg = (err && (err.message || String(err))) ? (err.message || String(err)) : 'Unbekannter Fehler';
          host.innerHTML = `
            <div class="card">
              <h3 style="margin:0 0 8px;">⚠️ Statistik: Anzeige-Fehler (${escapeHtml(label)})</h3>
              <div class="muted" style="font-size:12px; line-height:1.4;">
                Beim Laden dieses Bereichs ist ein Fehler aufgetreten. Bitte Seite neu laden. Falls es wiederkommt, schicke mir den Console-Fehlertext.
              </div>
              <div class="muted" style="margin-top:10px; font-size:12px;">
                <b>Fehler:</b> ${escapeHtml(msg)}
              </div>
            </div>
          `;
        }
      }
    };

    if(k==='capture') safeRender(renderStatCapture, 'Erfassung');
    else if(k==='analysis') safeRender(renderStatAnalysis, 'Analyse');
    else if(k==='export') safeRender(renderStatExport, 'Export');
    else if(k==='ratings') safeRender(renderStatRatings, 'Bewertungen');
    else safeRender(renderStatMethod, 'Methodik');
  };

  // default: analysis-first would be tempting, but for data collection: capture
  const def = state.__statSub || 'capture';
  ['capture','analysis','export','ratings','method'].forEach(k=>{
    const b=document.getElementById('statSub_'+k);
    if(b) b.onclick=()=>setActive(k);
  });
  setActive(def);
}

