/* ===== CHAT (M50.9.9GB170_FALLBACK_DIRECTCALL_CONTRACT_STAY_20260404_ROOTONLY) ===== */
function dsResolveOrgId(){
  const raw = [
    CLOUD && CLOUD.orgId,
    window.firebaseOrgId,
    window.CLOUD_ORG_ID,
    (window.firebaseConfig && window.firebaseConfig.orgId),
    localStorage.getItem('ds_orgId')
  ].find(v => String(v || '').trim());
  return String(raw || 'doggystyle').trim();
}
function dsEnsureChatDb(){
  try{
    if(CLOUD){
      const resolvedOrgId = dsResolveOrgId();
      if(resolvedOrgId) CLOUD.orgId = resolvedOrgId;
    }
    if(CLOUD && CLOUD.db) return CLOUD.db;
    const fb = (typeof firebase !== 'undefined' && firebase) ? firebase : window.firebase;
    const cfg = window.firebaseConfig || null;
    if(!fb || typeof fb.firestore !== 'function') return null;
    try{
      if(cfg && typeof fb.initializeApp === 'function' && (!fb.apps || !fb.apps.length)){
        fb.initializeApp(cfg);
      }
    }catch(_){ }
    const db = fb.firestore();
    if(CLOUD){
      CLOUD.enabled = true;
      CLOUD.db = db;
      if(!CLOUD.auth && typeof fb.auth === 'function'){
        try{ CLOUD.auth = fb.auth(); }catch(_){ }
      }
      if(!CLOUD.app && fb.apps && fb.apps.length){
        try{ CLOUD.app = fb.apps[0]; }catch(_){ }
      }
    }
    return db;
  }catch(_){
    return null;
  }
}
function cloudChatsCol(){
  const orgId = dsResolveOrgId();
  const db = dsEnsureChatDb();
  if(!db || !orgId || typeof db.collection !== 'function') return null;
  return db.collection("orgs").doc(orgId).collection("chats");
}
function cloudChatDoc(chatId){
  const col = cloudChatsCol();
  return col && chatId ? col.doc(String(chatId)) : null;
}
function cloudChatMessagesCol(chatId){
  const doc = cloudChatDoc(chatId);
  return doc ? doc.collection('messages') : null;
}
function dsServerTimestamp(){
  try{
    if(window.firebase && firebase.firestore && firebase.firestore.FieldValue && firebase.firestore.FieldValue.serverTimestamp){
      return firebase.firestore.FieldValue.serverTimestamp();
    }
  }catch(_){ }
  return Date.now();
}
function dsFieldValueIncrement(n){
  try{
    if(window.firebase && firebase.firestore && firebase.firestore.FieldValue && firebase.firestore.FieldValue.increment){
      return firebase.firestore.FieldValue.increment(Number(n || 0));
    }
  }catch(_){ }
  return Number(n || 0);
}
function dsUnreadCountForRole(chat, role){
  const data = chat || {};
  if(String(role||'') === 'staff') return Math.max(0, Number(data.unreadForStaff || 0));
  if(String(role||'') === 'customer') return Math.max(0, Number(data.unreadForCustomer || 0));
  return 0;
}
function dsEnsureBadgeChip(el){
  if(!el) return null;
  let chip = el.querySelector('.ds-chat-nav-badge');
  if(chip) return chip;
  chip = document.createElement('span');
  chip.className = 'ds-chat-nav-badge is-hidden';
  chip.textContent = '0';
  el.appendChild(chip);
  return chip;
}
function dsSetBadgeValue(el, count){
  const chip = dsEnsureBadgeChip(el);
  if(!chip) return;
  const safe = Math.max(0, Number(count || 0));
  chip.textContent = String(safe);
  chip.classList.toggle('is-hidden', safe <= 0);
}
function dsUpdateAdminUnreadBadge(){
  const el = document.getElementById('tabChat');
  const st = dsAdminChatState();
  const chats = Array.isArray(st?.chats) ? st.chats : [];
  const total = chats.reduce((sum, chat)=> sum + dsUnreadCountForRole(chat, 'staff'), 0);
  dsSetBadgeValue(el, total);
}
function dsUpdateCustomerUnreadBadge(){
  const el = document.querySelector('[data-view="chat"].nav-btn');
  const ws = dsUnreadWatchState();
  const fromWatcher = ws?.customerSeen instanceof Map ? Array.from(ws.customerSeen.values()) : [];
  const st = dsCustomerChatState();
  const chats = fromWatcher.length ? fromWatcher : (Array.isArray(st?.chats) ? st.chats : []);
  const total = chats.reduce((sum, chat)=> sum + dsUnreadCountForRole(chat, 'customer'), 0);
  dsSetBadgeValue(el, total);
}
async function dsMarkChatRead(chatId, role){
  const ref = cloudChatDoc(chatId);
  if(!ref || !chatId) return;
  const patch = String(role||'') === 'staff'
    ? { unreadForStaff: 0, staffLastReadAt: dsServerTimestamp(), staffLastReadAtMs: Date.now() }
    : { unreadForCustomer: 0, customerLastReadAt: dsServerTimestamp(), customerLastReadAtMs: Date.now() };
  try{ await ref.set(patch, { merge:true }); }catch(_){ }
}
function dsGetChatReadMs(chat, role){
  return String(role||'') === 'staff'
    ? Number(chat?.staffLastReadAtMs || dsTsMs(chat?.staffLastReadAt) || 0)
    : Number(chat?.customerLastReadAtMs || dsTsMs(chat?.customerLastReadAt) || 0);
}
function dsGetIncomingUnreadCount(messages, role, readMs){
  const safeRead = Number(readMs || 0);
  return (Array.isArray(messages) ? messages : []).reduce((sum, msg)=>{
    const msgMs = Number(msg?.createdAtMs || dsTsMs(msg?.createdAt) || 0);
    return String(msg?.senderRole || '') !== String(role || '') && msgMs > safeRead ? sum + 1 : sum;
  }, 0);
}
function dsPatchLocalChatReadState(chatId, role, readMs, unreadCount){
  const safeRead = Number(readMs || 0);
  const safeUnread = Math.max(0, Number(unreadCount || 0));
  const apply = (chat)=>{
    if(!chat || String(chat.id || '') !== String(chatId || '')) return chat;
    if(String(role || '') === 'staff'){
      chat.staffLastReadAtMs = safeRead;
      chat.unreadForStaff = safeUnread;
    }else{
      chat.customerLastReadAtMs = safeRead;
      chat.unreadForCustomer = safeUnread;
    }
    return chat;
  };
  try{
    const a = dsAdminChatState();
    a.chats = (a.chats || []).map(c=>apply(c));
    a.filteredChats = (a.filteredChats || []).map(c=>apply(c));
  }catch(_){ }
  try{
    const c = dsCustomerChatState();
    c.chats = (c.chats || []).map(x=>apply(x));
  }catch(_){ }
  try{
    const ws = dsUnreadWatchState();
    if(ws?.customerSeen instanceof Map && ws.customerSeen.has(String(chatId || ''))){
      const cur = ws.customerSeen.get(String(chatId || '')) || {};
      apply(cur);
      ws.customerSeen.set(String(chatId || ''), cur);
    }
  }catch(_){ }
}
async function dsMarkChatReadUpTo(chatId, role, readMs, messages){
  const safeRead = Number(readMs || 0);
  if(!chatId || !safeRead) return;
  const adminState = (()=>{ try{ return dsAdminChatState(); }catch(_){ return null; } })();
  const customerState = (()=>{ try{ return dsCustomerChatState(); }catch(_){ return null; } })();
  const localChat = (adminState?.chats || []).find(c=>String(c.id||'')===String(chatId||''))
    || (customerState?.chats || []).find(c=>String(c.id||'')===String(chatId||''))
    || null;
  const prevRead = dsGetChatReadMs(localChat, role);
  const nextRead = Math.max(prevRead, safeRead);
  const unreadCount = dsGetIncomingUnreadCount(messages, role, nextRead);
  const ref = cloudChatDoc(chatId);
  if(!ref) return;
  const patch = String(role||'') === 'staff'
    ? { unreadForStaff: unreadCount, staffLastReadAt: dsServerTimestamp(), staffLastReadAtMs: nextRead }
    : { unreadForCustomer: unreadCount, customerLastReadAt: dsServerTimestamp(), customerLastReadAtMs: nextRead };
  try{ await ref.set(patch, { merge:true }); }catch(_){ }
  dsPatchLocalChatReadState(chatId, role, nextRead, unreadCount);
  try{ dsUpdateAdminUnreadBadge(); }catch(_){ }
  try{ dsUpdateCustomerUnreadBadge(); }catch(_){ }
}
function dsLatestIncomingReadMs(messages, role){
  return (Array.isArray(messages) ? messages : []).reduce((max, msg)=>{
    if(String(msg?.senderRole || '') === String(role || '')) return max;
    const msgMs = Number(msg?.createdAtMs || dsTsMs(msg?.createdAt) || 0);
    return msgMs > max ? msgMs : max;
  }, 0);
}
function dsChatPreviewState(){
  if(!window.__dsChatPreviewState) window.__dsChatPreviewState = { open:false };
  return window.__dsChatPreviewState;
}
function dsEnsureChatPreviewModal(){
  let modal = document.getElementById('dsChatPreviewModal');
  if(modal) return modal;
  modal = document.createElement('div');
  modal.id = 'dsChatPreviewModal';
  modal.className = 'ds-chat-preview-modal is-hidden';
  modal.innerHTML = '<div class="ds-chat-preview-modal__backdrop" data-close="1"></div><div class="ds-chat-preview-modal__panel" role="dialog" aria-modal="true" aria-labelledby="dsChatPreviewTitle"><div class="ds-chat-preview-modal__head"><strong id="dsChatPreviewTitle">Nachricht</strong><div class="ds-chat-preview-modal__actions"><button type="button" class="btn danger is-hidden" id="btnDsChatDeleteMessage">Nachricht löschen</button><button type="button" class="btn" data-close="1">Schließen</button></div></div><div id="dsChatPreviewMeta" class="muted"></div><div id="dsChatPreviewBody" class="ds-chat-preview-modal__body"></div></div>';
  document.body.appendChild(modal);
  modal.addEventListener('click', (ev)=>{
    const target = ev.target;
    if(target && target.getAttribute && target.getAttribute('data-close') === '1') dsCloseChatPreviewModal();
  });
  return modal;
}
function dsNormalizeChatAttachments(list){
  return (Array.isArray(list) ? list : []).map((raw)=>{
    const url = String(raw?.url || raw?.downloadURL || '').trim();
    if(!url) return null;
    const kind = String(raw?.kind || raw?.type || raw?.mediaType || '').trim().toLowerCase();
    const contentType = String(raw?.contentType || '').trim().toLowerCase();
    const name = String(raw?.name || raw?.filename || raw?.title || '').trim();
    const path = String(raw?.path || '').trim();
    const size = Number(raw?.size || 0) || 0;
    const finalKind = kind === 'image' || contentType.startsWith('image/') ? 'image' : (kind === 'video' || contentType.startsWith('video/') ? 'video' : 'file');
    return { url, kind: finalKind, contentType, name, path, size };
  }).filter(Boolean);
}
function dsChatAttachmentSummary(attachments){
  const files = dsNormalizeChatAttachments(attachments);
  if(!files.length) return '';
  const images = files.filter(x=>x.kind === 'image').length;
  const videos = files.filter(x=>x.kind === 'video').length;
  const other = files.length - images - videos;
  const parts = [];
  if(images) parts.push(images + ' Bild' + (images === 1 ? '' : 'er'));
  if(videos) parts.push(videos + ' Video' + (videos === 1 ? '' : 's'));
  if(other) parts.push(other + ' Datei' + (other === 1 ? '' : 'en'));
  return parts.join(' · ');
}
function dsChatSnippetFromMessage(text, attachments){
  const clean = String(text || '').trim();
  if(clean) return clean.slice(0, 220);
  const summary = dsChatAttachmentSummary(attachments);
  return summary ? '📎 ' + summary : '';
}
function dsChatAttachmentHtml(attachments, compact){
  const files = dsNormalizeChatAttachments(attachments);
  if(!files.length) return '';
  return `<div class="ds-chat-attachments ${compact ? 'is-compact' : ''}">` + files.map((file)=>{
    const name = escapeHtml(file.name || (file.kind === 'image' ? 'Bild' : (file.kind === 'video' ? 'Video' : 'Datei')));
    if(file.kind === 'image') return `<a class="ds-chat-attachment ds-chat-attachment--image" href="${escapeHtml(file.url)}" target="_blank" rel="noopener" data-chat-media-link="1"><img src="${escapeHtml(file.url)}" alt="${name}" loading="lazy"/><span>${name}</span></a>`;
    if(file.kind === 'video') return `<div class="ds-chat-attachment ds-chat-attachment--video"><video controls preload="metadata" playsinline src="${escapeHtml(file.url)}"></video><a href="${escapeHtml(file.url)}" target="_blank" rel="noopener" data-chat-media-link="1">${name}</a></div>`;
    return `<a class="ds-chat-attachment ds-chat-attachment--file" href="${escapeHtml(file.url)}" target="_blank" rel="noopener" data-chat-media-link="1">📎 ${name}</a>`;
  }).join('') + '</div>';
}
function dsChatPreviewBodyHtml(msg){
  const text = String(msg?.text || '').trim();
  const files = dsNormalizeChatAttachments(msg?.attachments);
  const parts = [];
  if(text) parts.push(`<div class="ds-chat-preview-modal__text">${escapeHtml(text)}</div>`);
  if(files.length) parts.push(dsChatAttachmentHtml(files, false));
  if(!parts.length) parts.push('<div class="muted">Kein Inhalt.</div>');
  return parts.join('');
}
function dsCanDeleteChatMessage(msg, role, chat){
  if(!msg || !msg.id) return false;
  const ownRole = String(role || 'customer').trim().toLowerCase();
  if(ownRole === 'staff') return true;
  if(ownRole === 'customer' && dsIsChatOwnerClient(chat)) return true;
  const uid = String(dsChatUserUid() || '').trim();
  const email = String(dsChatUserEmail() || '').trim().toLowerCase();
  const msgUid = String(msg?.senderUid || '').trim();
  const msgEmail = String(msg?.senderEmail || '').trim().toLowerCase();
  if((uid && msgUid && uid === msgUid) || (email && msgEmail && email === msgEmail)) return true;
  const senderRole = String(msg?.senderRole || '').trim().toLowerCase();
  return senderRole === ownRole;
}
async function dsDeleteChatAttachmentFiles(msg){
  const files = dsNormalizeChatAttachments(msg?.attachments);
  if(!files.length) return;
  for(const file of files){
    try{
      if(file.path && window.firebase && firebase.storage){
        await firebase.storage().ref().child(file.path).delete();
      }
    }catch(err){ console.warn('chat attachment delete failed', err); }
  }
}
async function dsRefreshChatMetaFromMessages(chatId){
  if(!chatId) return;
  const chatRef = cloudChatDoc(chatId);
  const msgs = cloudChatMessagesCol(chatId);
  if(!chatRef || !msgs) return;
  const chatSnap = await chatRef.get().catch(()=>null);
  const chatData = (chatSnap && chatSnap.exists && typeof chatSnap.data === 'function') ? (chatSnap.data() || {}) : {};
  const readStaff = Number(chatData?.staffLastReadAtMs || dsTsMs(chatData?.staffLastReadAt) || 0);
  const readCustomer = Number(chatData?.customerLastReadAtMs || dsTsMs(chatData?.customerLastReadAt) || 0);
  const snap = await msgs.orderBy('createdAt','asc').get();
  const all = snap.docs.map(doc=>({ id: doc.id, ...(doc.data() || {}) }));
  const visible = all.filter(msg=> !msg?.deleted);
  const last = visible[visible.length - 1] || null;
  const unreadForStaff = visible.reduce((sum, msg)=> sum + ((String(msg?.senderRole || '') === 'customer' && Number(msg?.createdAtMs || dsTsMs(msg?.createdAt) || 0) > readStaff) ? 1 : 0), 0);
  const unreadForCustomer = visible.reduce((sum, msg)=> sum + ((String(msg?.senderRole || '') === 'staff' && Number(msg?.createdAtMs || dsTsMs(msg?.createdAt) || 0) > readCustomer) ? 1 : 0), 0);
  await chatRef.set({
    updatedAt: dsServerTimestamp(),
    updatedAtMs: Date.now(),
    lastMessageText: last ? dsChatSnippetFromMessage(last.text, last.attachments) : '',
    lastMessageFromRole: last ? String(last.senderRole || '') : '',
    lastMessageAt: last ? (last.createdAt || dsServerTimestamp()) : dsServerTimestamp(),
    lastMessageAtMs: last ? Number(last.createdAtMs || dsTsMs(last.createdAt) || Date.now()) : 0,
    unreadForStaff,
    unreadForCustomer
  }, { merge:true });
}
async function dsDeleteChatMessage(chatId, msg, role, rerender, chat){
  if(!chatId || !msg?.id) throw new Error('Nachricht konnte nicht gelöscht werden.');
  const messageId = String(msg.id || '').trim();
  if(!messageId) throw new Error('Nachricht konnte nicht gelöscht werden.');
  if(!dsCanDeleteChatMessage(msg, role, chat)) throw new Error('Diese Nachricht kann hier nicht gelöscht werden.');
  if(!confirm('Nachricht wirklich löschen?')) return false;
  if(!confirm('Wirklich endgültig löschen?')) return false;
  await dsDeleteChatAttachmentFiles(msg).catch(()=>{});
  await cloudChatMessagesCol(chatId).doc(messageId).delete();
  await dsRefreshChatMetaFromMessages(chatId).catch(console.warn);
  dsCloseChatPreviewModal();
  if(typeof rerender === 'function') rerender();
  return true;
}
function dsOpenChatPreviewModal(msg, role, chat, rerender){
  const modal = dsEnsureChatPreviewModal();
  if(!modal) return;
  const meta = modal.querySelector('#dsChatPreviewMeta');
  const body = modal.querySelector('#dsChatPreviewBody');
  const deleteBtn = modal.querySelector('#btnDsChatDeleteMessage');
  if(meta) meta.textContent = `${String(msg?.senderName || 'Nachricht')} · ${dsChatDisplayTime(msg?.createdAt || msg?.createdAtMs || 0)}`;
  if(body) body.innerHTML = dsChatPreviewBodyHtml(msg);
  if(deleteBtn){
    const canDelete = dsCanDeleteChatMessage(msg, role, chat);
    deleteBtn.classList.toggle('is-hidden', !canDelete);
    deleteBtn.onclick = async ()=>{
      try{ await dsDeleteChatMessage(chat?.id, msg, role, rerender, chat); }
      catch(err){ alert(String(err?.message || err || 'Löschen fehlgeschlagen.')); }
    };
  }
  modal.classList.remove('is-hidden');
  dsChatPreviewState().open = true;
}
function dsCloseChatPreviewModal(){
  const modal = document.getElementById('dsChatPreviewModal');
  if(modal) modal.classList.add('is-hidden');
  const deleteBtn = modal?.querySelector ? modal.querySelector('#btnDsChatDeleteMessage') : null;
  if(deleteBtn) deleteBtn.onclick = null;
  dsChatPreviewState().open = false;
}
function dsBindMessageBubbleClicks(container, role, chat, messages, rerender){
  if(!container) return;
  container.querySelectorAll('[data-chat-msg-index]').forEach(btn=>{
    if(btn.__chatMsgBound) return;
    btn.__chatMsgBound = true;
    btn.addEventListener('click', async (ev)=>{
      const target = ev.target;
      if(target && target.closest && target.closest('[data-chat-media-link="1"], video')) return;
      const idx = Number(btn.getAttribute('data-chat-msg-index') || -1);
      const msg = Array.isArray(messages) ? messages[idx] : null;
      if(!msg || msg.deleted) return;
      dsOpenChatPreviewModal(msg, role, chat, rerender);
      if(String(msg?.senderRole || '') !== String(role || '') && chat?.id){
        const msgMs = Number(msg?.createdAtMs || dsTsMs(msg?.createdAt) || 0);
        if(msgMs){
          await dsMarkChatReadUpTo(chat.id, role, msgMs, messages);
          if(typeof rerender === 'function') rerender();
        }
      }
    });
    btn.addEventListener('keydown', (ev)=>{
      if(ev.key === 'Enter' || ev.key === ' '){
        ev.preventDefault();
        btn.click();
      }
    });
  });
}
/* GB150: legacy duplicate chat preview helpers removed; the richer implementations above stay authoritative. */
function dsChatOpenIntentState(){
  if(!window.__dsChatOpenIntentState){
    window.__dsChatOpenIntentState = { staff:false, customer:false };
  }
  return window.__dsChatOpenIntentState;
}
function dsSetChatExplicitOpen(role, value){
  const st = dsChatOpenIntentState();
  st[String(role||'') === 'staff' ? 'staff' : 'customer'] = value !== false;
}
function dsHasChatExplicitOpen(role){
  const st = dsChatOpenIntentState();
  return !!st[String(role||'') === 'staff' ? 'staff' : 'customer'];
}
function dsUnreadWatchState(){
  if(!window.__dsUnreadWatchState){
    window.__dsUnreadWatchState = { started:false, adminUnsub:null, customerUnsubs:[], customerSeen:new Map() };
  }
  return window.__dsUnreadWatchState;
}
function dsPublishCustomerUnreadSeen(){
  const ws = dsUnreadWatchState();
  const st = dsCustomerChatState();
  st.chats = dsChatSortByUpdated(Array.from(ws.customerSeen.values()));
  dsUpdateCustomerUnreadBadge();
}
function dsStartAdminUnreadWatcher(){
  const ws = dsUnreadWatchState();
  if(ws.adminUnsub) return;
  const col = cloudChatsCol();
  if(!col || !dsChatAdminAllowed()) return;
  ws.adminUnsub = col.onSnapshot((snap)=>{
    const st = dsAdminChatState();
    st.chats = dsChatSortByUpdated(snap.docs.map(doc=>({ id: doc.id, ...(doc.data()||{}) })));
    st.filteredChats = dsChatFilterForTeam(st.chats, st.currentTeamKey || 'all');
    dsUpdateAdminUnreadBadge();
    if(document.getElementById('chatAdminList')) renderAdminChatList();
  }, (_err)=>{ dsUpdateAdminUnreadBadge(); });
}
function dsStartCustomerUnreadWatcher(){
  const ws = dsUnreadWatchState();
  if((ws.customerUnsubs || []).length) return;
  const col = cloudChatsCol();
  const uid = dsChatUserUid();
  const email = dsChatUserEmail();
  if(!col || (!uid && !email)) return;
  const seen = ws.customerSeen = new Map();
  const publish = ()=> dsPublishCustomerUnreadSeen();
  const attach = (q)=> q.onSnapshot((snap)=>{
    snap.docChanges().forEach(ch=>{
      if(ch.type === 'removed') seen.delete(ch.doc.id);
      else seen.set(ch.doc.id, { id: ch.doc.id, ...(ch.doc.data()||{}) });
    });
    publish();
  }, (_err)=> publish());
  const unsubs = [];
  if(uid) unsubs.push(attach(col.where('customerUid','==',uid)));
  if(email) unsubs.push(attach(col.where('customerEmail','==',email)));
  ws.customerUnsubs = unsubs;
  publish();
}
function dsInitUnreadBadgeWatchers(){
  const ws = dsUnreadWatchState();
  if(ws.started) return;
  ws.started = true;
  const tick = ()=>{
    try{
      if(!dsEnsureChatDb() || (!dsChatUserUid() && !dsChatUserEmail())) return;
      if(document.getElementById('tabChat') && dsChatAdminAllowed()) dsStartAdminUnreadWatcher();
      if(document.querySelector('[data-view="chat"].nav-btn')) dsStartCustomerUnreadWatcher();
    }catch(_){ }
  };
  tick();
  ws.timer = setInterval(tick, 2000);
}
function dsChatNowLabel(){ return fmtDT(Date.now()); }
function dsChatUserEmail(){ return String(CLOUD?.user?.email || '').trim().toLowerCase(); }
function dsChatUserUid(){ return String(CLOUD?.user?.uid || '').trim(); }
function dsChatCustomerProfile(){
  const email = dsChatUserEmail();
  const uid = dsChatUserUid();
  const customers = Array.isArray(state?.customers) ? state.customers : [];
  const fromState = customers.find(c=> String(c?.portalUid || c?.uid || '').trim() === uid)
    || customers.find(c=> String(c?.email || '').trim().toLowerCase() === email)
    || {};
  return {
    customerUid: uid || String(fromState?.portalUid || fromState?.uid || '').trim(),
    customerEmail: email || String(fromState?.email || '').trim().toLowerCase(),
    customerName: String(fromState?.name || CLOUD?.userProfile?.name || CLOUD?.user?.displayName || CLOUD?.user?.email || 'Kunde').trim(),
    customerId: String(fromState?.customerId || fromState?.id || fromState?.email || uid || email || '').trim()
  };
}
function dsIsChatOwnerClient(chat){
  const uid = dsChatUserUid();
  const email = dsChatUserEmail();
  const chatUid = String(chat?.customerUid || '').trim();
  const chatEmail = String(chat?.customerEmail || '').trim().toLowerCase();
  return !!((uid && chatUid && uid === chatUid) || (email && chatEmail && email === chatEmail));
}
function dsChatAdminAllowed(){
  try{
    if(isStaff()) return true;
    const email = dsChatUserEmail();
    const admins = Array.isArray(CLOUD?.adminEmails) ? CLOUD.adminEmails.map(x=>String(x||'').trim().toLowerCase()).filter(Boolean) : [];
    if(email && admins.includes(email)) return true;
    if(email === 'raphael@boch-plan.de') return true;
  }catch(_){ }
  return false;
}

function dsChatTeamMembers(){
  return [
    { key:'all', label:'Alle', fullLabel:'Alle Chats', roleLabel:'Übersicht', email:'' },
    { key:'raphael', label:'Raphael', fullLabel:'Raphael', roleLabel:'Inhaber', email:'raphael@boch-plan.de' },
    { key:'anschi', label:'Anschi', fullLabel:'Anschi', roleLabel:'Team', email:'anschi@doggystyle.local' }
  ];
}
function dsChatTeamByKey(key){
  const k = String(key || '').trim().toLowerCase();
  return dsChatTeamMembers().find(x=>x.key===k) || dsChatTeamMembers().find(x=>x.key==='raphael');
}
function dsChatInferStaffKey(){
  const email = dsChatUserEmail();
  if(email === 'raphael@boch-plan.de') return 'raphael';
  if(email && email.includes('anschi')) return 'anschi';
  const profileName = String(CLOUD?.userProfile?.name || CLOUD?.user?.displayName || '').trim().toLowerCase();
  if(profileName.includes('anschi') || profileName.includes('angelika')) return 'anschi';
  return 'raphael';
}
function dsChatNormalizeTeamKey(value, allowAll){
  const v = String(value || '').trim().toLowerCase();
  if(allowAll && v === 'all') return 'all';
  return dsChatTeamMembers().some(x=>x.key===v && x.key !== 'all') ? v : 'raphael';
}
function dsChatFilterForTeam(chats, teamKey){
  const key = dsChatNormalizeTeamKey(teamKey, true);
  const arr = Array.isArray(chats) ? chats : [];
  if(key === 'all') return dsChatSortByUpdated(arr);
  return arr.filter(chat=> dsChatNormalizeTeamKey(chat?.teamMemberKey || chat?.channel || '') === key);
}
function dsChatTargetLabel(teamKey){
  const item = dsChatTeamByKey(teamKey);
  return item?.fullLabel || item?.label || 'Team';
}

function dsChatErrorText(err){
  try{
    const code = String(err?.code || err?.name || '').trim();
    const msg = String(err?.message || err || '').trim();
    return [code, msg].filter(Boolean).join(' · ') || 'Unbekannter Fehler';
  }catch(_){ return 'Unbekannter Fehler'; }
}

async function dsEnsureWelcomeMessage(chatId, profile){
  const msgs = cloudChatMessagesCol(chatId);
  if(!msgs || !chatId) return false;
  try{
    const existing = await msgs.where('system','==',true).limit(1).get();
    if(existing && !existing.empty) return false;
  }catch(err){
    try{
      const fallback = await msgs.orderBy('createdAt','asc').limit(5).get();
      const hasWelcome = fallback.docs.some(doc=>{
        const d = doc.data() || {};
        return d.system === true || String(d.senderUid||'') === 'system' || String(d.senderName||'').toLowerCase().includes('doggy style team');
      });
      if(hasWelcome) return false;
    }catch(_){ }
  }
  await dsSeedWelcomeMessage(chatId, profile);
  return true;
}
function dsChatDisplayTime(v){
  try{
    if(v && typeof v.toDate === 'function') return fmtDT(v.toDate().getTime());
    if(v && typeof v.seconds === 'number') return fmtDT(v.seconds * 1000);
    return fmtDT(Number(v||0));
  }catch(_){ return '—'; }
}
async function dsSeedWelcomeMessage(chatId, profile){
  const msgs = cloudChatMessagesCol(chatId);
  if(!msgs) return;
  const now = Date.now();
  const welcomeText = [
    'Willkommen im Doggy Style Chat.',
    'Hier kannst du uns direkt zu Aufenthalt, Betreuung, Bring- und Abholzeiten oder Rückfragen schreiben.',
    'Wir antworten dir so schnell wie möglich direkt hier im Verlauf.'
  ].join(' ');
  await msgs.add({
    text: welcomeText,
    senderRole: 'staff',
    senderName: 'Doggy Style Team',
    senderUid: 'system',
    senderEmail: '',
    system: true,
    createdAt: now,
    createdAtMs: now,
    customerUid: profile?.customerUid || '',
    customerEmail: profile?.customerEmail || '',
    customerName: profile?.customerName || ''
  });
}
function dsChatSortByUpdated(arr){
  return (Array.isArray(arr) ? arr.slice() : []).sort((a,b)=>{
    const av = Number(a?.updatedAtMs || a?.lastMessageAtMs || a?.createdAtMs || 0);
    const bv = Number(b?.updatedAtMs || b?.lastMessageAtMs || b?.createdAtMs || 0);
    return bv - av;
  });
}
async function dsFindCurrentCustomerChats(teamKey){
  const col = cloudChatsCol();
  if(!col) return [];
  const uid = dsChatUserUid();
  const email = dsChatUserEmail();
  const all = new Map();
  if(uid){
    try{
      const snap = await col.where('customerUid','==',uid).get();
      snap.forEach(doc=> all.set(doc.id, { id: doc.id, ...(doc.data()||{}) }));
    }catch(e){ console.warn('chat by uid failed', e); }
  }
  if(email){
    try{
      const snap = await col.where('customerEmail','==',email).get();
      snap.forEach(doc=> all.set(doc.id, { id: doc.id, ...(doc.data()||{}) }));
    }catch(e){ console.warn('chat by email failed', e); }
  }
  const filtered = dsChatFilterForTeam(Array.from(all.values()), teamKey || dsCustomerChatState().currentTeamKey);
  return dsChatSortByUpdated(filtered);
}
async function ensureCurrentCustomerChat(teamKey){
  const chosenTeamKey = dsChatNormalizeTeamKey(teamKey || dsCustomerChatState().currentTeamKey);
  const existing = await dsFindCurrentCustomerChats(chosenTeamKey);
  if(existing.length){
    try{ await dsEnsureWelcomeMessage(existing[0].id, dsChatCustomerProfile()); }catch(e){ console.warn('welcome ensure failed', e); }
    return existing[0];
  }
  const col = cloudChatsCol();
  if(!col) throw new Error('Cloud-Chat ist nicht verfügbar.');
  const profile = dsChatCustomerProfile();
  const now = Date.now();
  const payload = {
    customerUid: profile.customerUid || '',
    customerEmail: profile.customerEmail || '',
    customerName: profile.customerName || 'Kunde',
    customerId: profile.customerId || '',
    createdAt: dsServerTimestamp(),
    updatedAt: dsServerTimestamp(),
    createdAtMs: now,
    updatedAtMs: now,
    lastMessageText: '',
    lastMessageAt: dsServerTimestamp(),
    lastMessageAtMs: now,
    lastMessageFromRole: '',
    status: 'open',
    unreadForStaff: 0,
    unreadForCustomer: 0,
    teamMemberKey: chosenTeamKey,
    teamMemberLabel: dsChatTargetLabel(chosenTeamKey)
  };
  const ref = await col.add(payload);
  try{ await dsSeedWelcomeMessage(ref.id, profile); }catch(e){ console.warn('welcome message failed', e); }
  return { id: ref.id, ...payload };
}
async function dsSendChatMessage(chatId, text, extraMeta){
  const clean = String(text || '').trim();
  const meta = (extraMeta && typeof extraMeta === 'object') ? { ...extraMeta } : {};
  const attachments = dsNormalizeChatAttachments(meta.attachments);
  if(!clean && !attachments.length) throw new Error('Bitte zuerst eine Nachricht oder ein Bild/Video eingeben.');
  const msgs = cloudChatMessagesCol(chatId);
  const chatRef = cloudChatDoc(chatId);
  if(!msgs || !chatRef) throw new Error('Chat ist nicht verfügbar.');
  const now = Date.now();
  let existing = {};
  try{
    const snap = await chatRef.get();
    existing = (snap && snap.exists && typeof snap.data === 'function') ? (snap.data() || {}) : {};
  }catch(_){ existing = {}; }

  const adminState = dsAdminChatState();
  const customerState = dsCustomerChatState();
  const isAdminContext = !!(
    (adminState && String(adminState.currentChatId || '') === String(chatId || ''))
    || document.getElementById('chatAdminInput')
    || document.getElementById('chatAdminMessages')
  );
  const forcedRole = String(meta.forceSenderRole || '').trim().toLowerCase();
  const senderRole = forcedRole === 'staff' || forcedRole === 'customer'
    ? forcedRole
    : (isAdminContext || isStaff() ? 'staff' : 'customer');
  const viewerProfile = dsChatCustomerProfile();
  const rawTeamKey = (
    meta.teamMemberKey
    || existing.teamMemberKey
    || (senderRole === 'staff' ? adminState.currentTeamKey : customerState.currentTeamKey)
    || dsChatInferStaffKey()
  );
  const teamKey = dsChatNormalizeTeamKey(rawTeamKey, true) === 'all'
    ? dsChatInferStaffKey()
    : dsChatNormalizeTeamKey(rawTeamKey);
  const senderName = String(
    meta.senderName || (
      senderRole === 'staff'
        ? (function(){
            const explicit = dsChatNormalizeTeamKey(teamKey, true);
            if(explicit === 'raphael') return 'Raphael';
            if(explicit === 'anschi') return 'Anschi';
            return 'Doggy Style Team';
          })()
        : (viewerProfile.customerName || CLOUD?.user?.displayName || CLOUD?.user?.email || 'Kunde')
    )
  ).trim() || (senderRole === 'staff' ? 'Doggy Style Team' : 'Kunde');

  const customerMeta = senderRole === 'staff'
    ? {
        customerUid: String(existing.customerUid || meta.customerUid || '').trim(),
        customerEmail: String(existing.customerEmail || meta.customerEmail || '').trim().toLowerCase(),
        customerName: String(existing.customerName || meta.customerName || 'Kunde').trim(),
        customerId: String(existing.customerId || meta.customerId || existing.customerEmail || existing.customerUid || '').trim()
      }
    : {
        customerUid: viewerProfile.customerUid || '',
        customerEmail: viewerProfile.customerEmail || '',
        customerName: viewerProfile.customerName || 'Kunde',
        customerId: viewerProfile.customerId || ''
      };
  if(senderRole === 'staff' && !customerMeta.customerEmail && !customerMeta.customerUid && !customerMeta.customerId){
    throw new Error('Kundenchat konnte nicht geöffnet werden.');
  }
  delete meta.forceSenderRole;
  delete meta.senderName;
  delete meta.senderUid;
  delete meta.senderEmail;
  delete meta.attachments;

  const snippet = dsChatSnippetFromMessage(clean, attachments);
  await chatRef.set({
    customerUid: customerMeta.customerUid || '',
    customerEmail: customerMeta.customerEmail || '',
    customerName: customerMeta.customerName || 'Kunde',
    customerId: customerMeta.customerId || '',
    updatedAt: dsServerTimestamp(),
    updatedAtMs: now,
    lastMessageAt: dsServerTimestamp(),
    lastMessageAtMs: now,
    lastMessageText: snippet,
    lastMessageFromRole: senderRole,
    status: 'open',
    unreadForStaff: senderRole === 'customer' ? dsFieldValueIncrement(1) : 0,
    unreadForCustomer: senderRole === 'staff' ? dsFieldValueIncrement(1) : 0,
    teamMemberKey: teamKey,
    teamMemberLabel: dsChatTargetLabel(teamKey),
    ...(meta || {})
  }, { merge:true });
  await msgs.add({
    text: clean,
    attachments,
    senderRole,
    senderUid: String(meta.senderUid || dsChatUserUid() || '').trim(),
    senderEmail: String(meta.senderEmail || dsChatUserEmail() || '').trim(),
    senderName,
    createdAt: dsServerTimestamp(),
    createdAtMs: now,
    customerUid: customerMeta.customerUid || '',
    customerEmail: customerMeta.customerEmail || '',
    customerName: customerMeta.customerName || '',
    teamMemberKey: teamKey
  });
}
function dsTsMs(v){
  try{
    if(v == null) return 0;
    if(typeof v === 'number') return Number(v) || 0;
    if(typeof v?.toMillis === 'function') return Number(v.toMillis()) || 0;
    if(typeof v?.seconds === 'number') return Number(v.seconds) * 1000 + Math.round(Number(v.nanoseconds || 0) / 1e6);
    const d = new Date(v);
    const t = d.getTime();
    return Number.isFinite(t) ? t : 0;
  }catch(_){ return 0; }
}
function dsMessageReadStateLabel(msg, ownRole, chat){
  const msgMs = Number(msg?.createdAtMs || dsTsMs(msg?.createdAt) || 0);
  if(!msgMs) return '';
  const role = String(ownRole || 'customer');
  const own = String(msg?.senderRole || '') === role;
  const readMs = own
    ? (role === 'staff' ? Number(chat?.customerLastReadAtMs || dsTsMs(chat?.customerLastReadAt) || 0) : Number(chat?.staffLastReadAtMs || dsTsMs(chat?.staffLastReadAt) || 0))
    : (role === 'staff' ? Number(chat?.staffLastReadAtMs || dsTsMs(chat?.staffLastReadAt) || 0) : Number(chat?.customerLastReadAtMs || dsTsMs(chat?.customerLastReadAt) || 0));
  return readMs >= msgMs ? 'gelesen' : 'ungelesen';
}
function dsRenderChatMessages(messages, ownRole, chat){
  if(!Array.isArray(messages) || !messages.length){
    return '<div class="ds-chat-empty">Noch keine Nachrichten vorhanden.</div>';
  }
  return messages.map((msg, idx)=>{
    const own = String(msg?.senderRole || '') === String(ownRole || '');
    const meta = `${escapeHtml(msg?.senderName || (own ? 'Du' : 'Nachricht'))} · ${escapeHtml(dsChatDisplayTime(msg?.createdAt || msg?.createdAtMs || 0))}`;
    const status = dsMessageReadStateLabel(msg, ownRole, chat);
    const statusHtml = status ? `<div class="ds-chat-bubble__status ${status === 'gelesen' ? 'is-read' : 'is-unread'}">${escapeHtml(status)}</div>` : '';
    const deletedHtml = msg?.deleted ? '<div class="ds-chat-deleted">Nachricht gelöscht.</div>' : '';
    const textHtml = !msg?.deleted && String(msg?.text || '').trim() ? `<div class="ds-chat-bubble__text">${escapeHtml(msg?.text || '')}</div>` : '';
    const mediaHtml = !msg?.deleted ? dsChatAttachmentHtml(msg?.attachments, true) : '';
    const deletable = dsCanDeleteChatMessage(msg, ownRole, chat) ? '<span class="ds-chat-delete-chip">Löschen</span>' : '';
    return `<div class="ds-chat-msg ${own ? 'is-own' : ''}"><div class="ds-chat-bubble ${msg?.deleted ? 'is-deleted' : ''}" data-chat-msg-index="${idx}" tabindex="0" role="button" aria-label="Nachricht öffnen"><div class="ds-chat-bubble__meta">${meta}${deletable}</div>${deletedHtml}${textHtml}${mediaHtml}${statusHtml}</div></div>`;
  }).join('');
}
